/* ================= PIATTAFORMA «SEMESTRE FILTRO»: STATO E SALVATAGGIO =================
   Un solo stato (chiave semestre-v1) con una sezione per esame: exams.fis / exams.chi / exams.bio.
   Ogni esame del registro EXAMS usa lo stesso motore (argomenti, test, esercizi, simulazione). */
const KEY="semestre-v1",OLDKEY="fisica-v1";
const APP_URL="https://f6kd4bp6sr-stack.github.io/mie-app/semestre/";
const EDEF={pt:null,tp:{},qs:{},sims:[],run:null,days:{},hist:[],goal:null,goalsDone:[],ptDraft:null};
const $=id=>document.getElementById(id);
const esc=s=>String(s==null?"":s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const pad=n=>("0"+n).slice(-2);
const today=()=>{const d=new Date();return d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());};
const dOf=s=>{const [y,m,d]=s.split("-").map(Number);return new Date(y,m-1,d);};
const iso=d=>d.getFullYear()+"-"+pad(d.getMonth()+1)+"-"+pad(d.getDate());
const daysTo=s=>Math.round((dOf(s)-dOf(today()))/864e5);
const artD=s=>[8,11].includes(dOf(s).getDate())?"l'":"il ";
const fmtD=(s,o)=>dOf(s).toLocaleDateString("it-IT",o||{day:"numeric",month:"short"});
const ename=id=>EXAMS[id].short||EXAMS[id].t;
/* id stabili delle domande: esame + hash del testo */
(function(){const h=s=>{let x=5381;for(let i=0;i<s.length;i++)x=((x<<5)+x+s.charCodeAt(i))|0;return (x>>>0).toString(36);};
  /* opzioni rimescolate in modo stabile (sempre uguale per la stessa domanda): la risposta giusta non sta sempre nella stessa lettera */
  const mix=(q,seed)=>{if(!Array.isArray(q.o)||typeof q.a!=="number"||q.mixed)return;let x=parseInt(h(seed),36)||1;const rnd=()=>{x^=x<<13;x^=x>>>17;x^=x<<5;return (x>>>0)/4294967296;};
    const idx=q.o.map((_,i)=>i);for(let i=idx.length-1;i>0;i--){const j=Math.floor(rnd()*(i+1));[idx[i],idx[j]]=[idx[j],idx[i]];}q.o=idx.map(i=>q.o[i]);if(Array.isArray(q.e))q.e=idx.map(i=>q.e[i]);q.a=idx.indexOf(q.a);q.mixed=1;};
  EXORD.forEach(k=>{const E=EXAMS[k],tp=Object.fromEntries(E.topics.map(t=>[t.id,t]));E.qb.forEach(q=>{q.id=k+"-"+h(q.q);q.u=tp[q.t].u;mix(q,q.id);});E.pt.forEach((q,i)=>mix(q,k+"pt"+i+q.q));});})();
function normE(e){const o=JSON.parse(JSON.stringify(EDEF));if(e&&typeof e==="object"){Object.assign(o,e);o.tp=e.tp||{};o.qs=e.qs||{};o.sims=Array.isArray(e.sims)?e.sims:[];o.days=e.days||{};o.hist=Array.isArray(e.hist)?e.hist:[];o.goalsDone=Array.isArray(e.goalsDone)?e.goalsDone:[];}return o;}
function norm(r){const o={ver:2,savedAt:null,school:null,exams:{},sum:null};if(r&&typeof r==="object"){o.savedAt=r.savedAt||null;o.school=r.school||null;if(r.ui&&typeof r.ui==="object")o.ui=r.ui;if(r.diag)o.diag=r.diag;if(Array.isArray(r.diagLog))o.diagLog=r.diagLog;if(r.cpFix)o.cpFix=r.cpFix;}EXORD.forEach(k=>o.exams[k]=normE(r&&r.exams&&r.exams[k]));return o;}
function migrate(old){/* da «Fisica» (fisica-v1) alla piattaforma */const r=norm(null);r.school=old.school||null;r.exams.fis=normE(old);r.savedAt=old.savedAt||null;return r;}
function load(){let r=null;try{r=JSON.parse(localStorage.getItem(KEY)||"null");}catch(e){}
  if(!r){try{const o=JSON.parse(localStorage.getItem(OLDKEY)||"null");if(o)return migrate(o);}catch(e){}}return norm(r);}
let Rt=load();
const DBN="semestre-filtro";
function kv(name){return new Promise((res,rej)=>{try{const r=indexedDB.open(name||DBN,1);r.onupgradeneeded=()=>{if(!r.result.objectStoreNames.contains("kv"))r.result.createObjectStore("kv");};r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);}catch(e){rej(e);}});}
function idb(mode,k,v,name){return kv(name).then(db=>new Promise((res,rej)=>{const tx=db.transaction("kv",mode),st=tx.objectStore("kv"),q=mode==="readonly"?st.get(k):st.put(v,k);q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error);}));}
let svT=null;
function save(){Rt.savedAt=new Date().toISOString();Rt.sum=summaryAll();const t=JSON.stringify(Rt);try{localStorage.setItem(KEY,t);}catch(e){}clearTimeout(svT);svT=setTimeout(()=>idb("readwrite","semestre",t).catch(()=>{}),300);paintSaved();}
window.__flush=()=>{try{const t=JSON.stringify(Rt);localStorage.setItem(KEY,t);idb("readwrite","semestre",t).catch(()=>{});}catch(e){}};
function paintSaved(){const e=$("fzSaved");if(e)e.textContent=Rt.savedAt?"💾 Salvato automaticamente alle "+new Date(Rt.savedAt).toLocaleTimeString("it-IT",{hour:"2-digit",minute:"2-digit"})+" su questo dispositivo":"💾 Salvataggio automatico attivo";}
async function oldDb(){/* prima versione: copia nel database condiviso con Pianificazione (solo se esiste già) */
  try{if(!indexedDB.databases)return null;const l=await indexedDB.databases();if(!l.some(x=>x.name==="licenze-marco"))return null;
   const t=await idb("readonly","semestre",null,"licenze-marco");if(t)return JSON.parse(t);const f=await idb("readonly","fisica",null,"licenze-marco");return f?migrate(JSON.parse(f)):null;}catch(e){return null;}}
async function recover(){try{let t=await idb("readonly","semestre");let o=t?JSON.parse(t):null;
  if(!o)o=await oldDb();
  if(o&&(!Rt.savedAt||String(o.savedAt||"")>String(Rt.savedAt))){Rt=norm(o);useExam(EX);try{localStorage.setItem(KEY,JSON.stringify(Rt));}catch(e){}render();toast("Dati recuperati dalla copia del dispositivo");}}catch(e){}}
function toast(m){const e=$("toast");e.textContent=m;e.classList.add("on");clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove("on"),2200);}

/* ================= MOTORE DI UN ESAME ================= */
let EX="fis",E,UNITS,UN,TOPICS,TP,QB,QI,PT,S;
function useExam(id){EX=id;E=EXAMS[id];UNITS=E.units;UN=Object.fromEntries(UNITS.map(u=>[u.id,u]));TOPICS=E.topics;TP=Object.fromEntries(TOPICS.map(t=>[t.id,t]));QB=E.qb;QI=new Proxy(Object.fromEntries(QB.map(q=>[q.id,q])),{get:(o,k)=>o[k]||(typeof k==="string"&&k.startsWith("g~")?genQ(k):undefined)});PT=E.pt;S=Rt.exams[id];}
function withExam(id,fn){const p=EX;useExam(id);try{return fn();}finally{useExam(p);}}
useExam("fis");
const hasQ=id=>QB.some(q=>q.t===id);
function tScore(id){const s=S.tp[id]||{};if(!hasQ(id)){return Math.max(s.st?30:0,[0,15,50,80][s.self||0]);}
  const n=(s.ok||0)+(s.ko||0),acc=n?(s.ok||0)/n:0,conf=Math.min(1,n/4);return Math.round(100*((s.st?.3:0)+.7*acc*conf));}
function uScore(u){const ts=TOPICS.filter(t=>t.u===u);return Math.round(ts.reduce((a,t)=>a+tScore(t.id),0)/ts.length);}
function overall(){return Math.round(UNITS.reduce((a,u)=>a+uScore(u.id)*u.q,0)/31);}
function stLab(sc){return sc>=80?["Padroneggiato","ok"]:sc>=50?["Quasi","acc"]:sc>0?["In corso","soon"]:["Da iniziare",""];}
function rec(q,ok){const key=q.gen?"g~"+q.g:q.id;const s=S.qs[key]||{ok:0,ko:0};ok?s.ok++:s.ko++;s.last=ok?1:0;s.d=today();S.qs[key]=s;const t=S.tp[q.t]||{};ok?t.ok=(t.ok||0)+1:t.ko=(t.ko||0)+1;t.d=today();S.tp[q.t]=t;S.days[today()]=(S.days[today()]||0)+1;}
function ptLevel(u){if(!S.pt)return null;const r=S.pt.unit[u];return r?r[0]:null;}
function plan(){const start=dOf(today()),end=dOf("2026-11-30");const D=Math.max(7,Math.round((end-start)/864e5)+1);
  const w=UNITS.map(u=>{const l=ptLevel(u.id);const weak=l==null?.5:1-l/2;return u.cfu*(1+weak)*(1-.6*uScore(u.id)/100);});
  const tot=w.reduce((a,b)=>a+b,0);let d=new Date(start),out=[];
  if(start<=end){UNITS.forEach((u,i)=>{const n=Math.max(2,Math.round(D*w[i]/tot));const a=new Date(d);d.setDate(d.getDate()+n);const b=new Date(d);b.setDate(b.getDate()-1);out.push({u,a:iso(a),b:iso(b)});});
   const last=out[out.length-1];if(dOf(last.b)>end){last.b=iso(end);if(dOf(last.b)<dOf(last.a))last.a=last.b;}}
  const lb=out.length?dOf(out[out.length-1].b).getTime()+864e5:start.getTime();
  out.push({x:"Ripasso, simulazioni a tempo, errori",a:iso(new Date(Math.max(lb,dOf("2026-12-01").getTime()))),b:"2026-12-09"});
  out.push({x:"1° appello nazionale, ore 11",a:EXAM1,b:EXAM1,ex:1});
  out.push({x:"Ripasso mirato sugli errori (se serve o per migliorare il voto)",a:"2026-12-11",b:"2027-01-10"});
  out.push({x:"2° appello nazionale, ore 11",a:EXAM2,b:EXAM2,ex:1});return out;}
function nextTopic(){const t=today(),pl=plan(),cur=pl.find(x=>x.u&&t>=x.a&&t<=x.b);
  const pool=cur?TOPICS.filter(x=>x.u===cur.u.id):TOPICS;const cand=pool.filter(x=>tScore(x.id)<80);
  const list=cand.length?cand:TOPICS.filter(x=>tScore(x.id)<80);if(!list.length)return null;
  return list.sort((a,b)=>tScore(a.id)-tScore(b.id)||TOPICS.indexOf(a)-TOPICS.indexOf(b))[0];}
function summary(){const nt=nextTopic(),ls=S.sims[S.sims.length-1];return{t:ename(EX),ic:E.ic,ready:E.ready,overall:overall(),units:Object.fromEntries(UNITS.map(u=>[u.id,{t:u.t,ic:u.ic,s:uScore(u.id)}])),
  next:nt?{id:nt.id,t:nt.t,u:UN[nt.u].t}:null,pt:S.pt?{score:S.pt.score,n:ptSel(S.pt).length,lev:S.pt.lev,date:S.pt.date}:null,sim:ls?{pts:sim31(ls),lab:simLab(ls),date:ls.date,pass:sim31(ls)>=18}:null,
  week:Object.entries(S.days).filter(([d])=>daysTo(d)>-7).reduce((a,[,n])=>a+n,0),studied:TOPICS.filter(t=>(S.tp[t.id]||{}).st).length,topics:TOPICS.length};}
function summaryAll(){const o={date:new Date().toISOString(),exams:{}};EXORD.forEach(k=>o.exams[k]=withExam(k,summary));return o;}

/* conferma senza finestre di dialogo: il primo tocco chiede conferma sul pulsante stesso, il secondo (entro 5 s) esegue */
function armed(b,msg){if(b.dataset.armed){if(Date.now()-(+b.dataset.armed)<600)return false;delete b.dataset.armed;clearTimeout(b._t);if(b._txt!=null)b.textContent=b._txt;return true;}
  b._txt=b.textContent;b.dataset.armed=Date.now();b.textContent=msg;b.classList.add("armed");b._t=setTimeout(()=>{delete b.dataset.armed;b.textContent=b._txt;b.classList.remove("armed");},5000);return false;}
/* ================= QUIZ ================= */
const nrm=s=>String(s||"").toUpperCase().normalize("NFD").replace(/[̀-ͯ]/g,"").replace(/\s+/g,"").replace(/,/g,".").replace(/−/g,"-");
/* valori numerici possibili di una risposta scritta (gestisce 20.0, 3,0, 49.050 / 49 050, 4,9·10^4, 4.9e4, unità dopo il numero) */
const SUPN="⁰¹²³⁴⁵⁶⁷⁸⁹";
function numVals(v,strict){let t=String(v==null?"":v).trim().replace(/−/g,"-").replace(/[\u00a0\u202f]/g," ");
  t=t.replace(/10\s*([⁻⁰¹²³⁴⁵⁶⁷⁸⁹]+)/g,(m,e)=>"10^"+e.replace(/⁻/g,"-").split("").map(c=>SUPN.indexOf(c)>=0?SUPN.indexOf(c):c).join(""));
  const m=t.match(/^([-+]?(?:\d[\d.,' ]*\d|\d))\s*(?:(?:[·x×*]|\. )\s*10\s*\^\s*([-+]?\d+)|[eE]([-+]?\d+))?(.*)$/);if(!m)return [];
  const rest=m[4]||"";if(strict&&rest.trim())return [];if(/\d/.test(rest.replace(/[a-zA-Zµ°][²³\d]/g,"").replace(/[²³]/g,"")))return [];
  const ex=+(m[2]||m[3]||0),raw=m[1].replace(/[' ]/g,""),cand=new Set();
  const dots=(raw.match(/\./g)||[]).length,coms=(raw.match(/,/g)||[]).length;
  if(dots&&coms){const last=Math.max(raw.lastIndexOf("."),raw.lastIndexOf(","));cand.add(raw.slice(0,last).replace(/[.,]/g,"")+"."+raw.slice(last+1));}
  else if(dots+coms===0)cand.add(raw);
  else if(dots+coms>1)cand.add(raw.replace(/[.,]/g,""));
  else{const r2=raw.replace(",",".");cand.add(r2);if(/^[-+]?\d{1,3}[.,]\d{3}$/.test(raw))cand.add(raw.replace(/[.,]/g,""));}
  return [...cand].map(x=>parseFloat(x)*Math.pow(10,ex)).filter(isFinite);}
const cpOK=(q,v)=>{if(q.a.map(nrm).includes(nrm(v)))return true;
  const want=q.a.map(a=>numVals(a,true)).filter(x=>x.length).flat();if(!want.length)return false;
  const got=numVals(v,false);return got.some(g=>want.some(w=>Math.abs(g-w)<=1e-9*Math.max(1,Math.abs(w))));};
const L5="ABCDE";
/* ordine delle opzioni diverso a ogni prova (stesso ordine se si riapre la stessa prova): le lettere seguono la posizione */
const SESS=(Math.random()*1e9|0).toString(36);
function ordOf(q,salt){const n=(q.o||[]).length,idx=[...Array(n).keys()];if(!salt)return idx;let x=0;const s=(q.id||q.q)+"|"+salt;for(let i=0;i<s.length;i++)x=((x<<5)-x+s.charCodeAt(i))|0;x=x||1;
  for(let i=n-1;i>0;i--){x^=x<<13;x^=x>>>17;x^=x<<5;const j=(x>>>0)%(i+1);[idx[i],idx[j]]=[idx[j],idx[i]];}return idx;}
const optsHTML=(q,salt,sel)=>ordOf(q,salt).map((j,p)=>`<button class="opt${sel===j?" sel":""}" type="button" data-o="${j}"><i>${L5[p]}</i><span>${esc(q.o[j])}</span></button>`).join("");
const letOf=(q,salt,j)=>L5[ordOf(q,salt).indexOf(j)];
/* testo della risposta giusta di un completamento, leggibile (non tutto maiuscolo) */
const cpShow=a=>{const t=String(a);return /^[A-ZÀ-Ý' -]{5,}$/.test(t)?t.toLowerCase():t;};
function qHTML(q,i,ctx,salt){salt=salt||(ctx==="pr"&&PR?PR.seed:SESS);const head=`<div class="qh"><span class="qn">${i!=null?i+".":""}</span><div class="qt">${esc(q.q)}${realTag(q)}</div></div>`;
  const st=S.qs[q.gen?"g~"+q.g:q.id],badge=ctx==="tp"&&st?`<span class="pill ${st.last?"ok":"warn"}" style="margin-left:6px;font-size:11px">${st.last?"✓ già risolta":"✗ da rivedere"}</span>`:"";
  if(q.k==="m")return `<div class="q" data-q="${q.id}" data-ctx="${ctx}" data-salt="${salt}">${head.replace('</div></div>',badge+'</div></div>')}<div class="opts">${optsHTML(q,salt)}</div><div class="solw"></div></div>`;
  const num=q.a.some(x=>/^[-−]?[\d.,]+$/.test(String(x)));
  return `<div class="q" data-q="${q.id}" data-ctx="${ctx}">${head.replace('</div></div>',badge+'</div></div>')}<div class="cpl"><input type="text" autocomplete="off" autocapitalize="${num?"off":"characters"}" inputmode="${num?"decimal":"text"}" spellcheck="false" placeholder="${num?"Scrivi il numero":"Scrivi la risposta"}" aria-label="Risposta"><button class="btn sm pri" type="button" data-chk>Verifica</button><button class="btn sm" type="button" data-skip>Non so</button></div><div class="solw"></div></div>`;}
function answerImmediate(box,q,val){if(box.dataset.done)return;box.dataset.done=1;let ok;
  if(q.k==="m"){ok=val===q.a;box.querySelectorAll(".opt").forEach(b=>{const j=+b.dataset.o;b.disabled=true;if(j===q.a)b.classList.add("right");else if(j===val)b.classList.add("wrong");});}
  else{const inp=box.querySelector("input");ok=val!=null&&cpOK(q,val);inp.disabled=true;inp.classList.add(ok?"right":"wrong");box.querySelectorAll(".cpl button").forEach(b=>b.disabled=true);}
  box.querySelector(".solw").innerHTML=`<div class="sol">${ok?'<b class="okc">✓ Giusto.</b>':'<b class="koc">✗ '+(val==null?"Saltata.":"Sbagliato.")+'</b> Risposta: <b>'+esc(q.k==="m"?letOf(q,box.dataset.salt,q.a)+") "+q.o[q.a]:cpShow(q.a[0]))+"</b>."} ${esc(q.s||"")}</div>`;
  rec(q,ok);try{logAns(box.dataset.ctx,q,val,ok);}catch(e){}save();return ok;}

/* ================= NAVIGAZIONE ================= */
const PLAT=[["home","🩺","Semestre filtro"],["novita","📰","Novità del giorno"],["cerca","🔎","Cerca"],["guida","ℹ️","Che cosa fa l'app"],["regole","🎓","Regole e UPO"],["fonti","🔗","Fonti"],["prog","📈","Progressi e copie"],["installa","📲","Installa su altri iPad"]];
function exSects(){const s=[["","🏠","Percorso"]];if(PT.length)s.push(["test","🧭","Test d'ingresso"]);s.push(["arg","📚",E.ready?"Argomenti":"Programma"]);
  if(QB.length){s.push(["es","✏️","Esercizi"]);s.push(["sim","⏱️","Simulazione"]);s.push(["storico","🗂️","Errori e storico"]);}if(TOPICS.some(t=>t.form))s.push(["form",E.formLab?"📌":"📐",E.formT||"Formulario"]);s.push(["info","📜","Storia e syllabus"]);return s;}
let view="home",curT=null,PR=null,SIMV=null,simTimer=null,PTA=null,argU=null;
function route(){const h=decodeURIComponent((location.hash||"").slice(1));const p=h.split("/");
  if(EXAMS[p[0]]){if(p[0]!==EX){useExam(p[0]);PR=null;SIMV=null;PTA=null;}
    HID=p[1]==="storico"&&p[2]?p[2]:null;if(p[1]==="t"&&TP[p[2]]){view="arg";curT=p[2];}else{curT=null;view=exSects().some(s=>s[0]===(p[1]||""))?"ex:"+(p[1]||""):"ex:";}}
  else{curT=null;const al={news:"novita",novità:"novita",notizie:"novita",info:"guida",ricerca:"cerca"};const hh=al[h]||h;view=PLAT.some(s=>s[0]===hh)?hh:"home";if(hh!==h)history.replaceState(null,"","#"+hh);}render();}
function go(h){if(location.hash!=="#"+h)location.hash=h;else route();}
const exView=()=>view.startsWith("ex:")||view==="arg";
function side(){const inEx=exView(),nc=newsCounts();let o=PLAT.map(([k,i,t])=>`<button data-go="${k}" class="${view===k?"on":""}"${view===k?' aria-current="page"':""}><span class="ic">${i}</span>${t}</button>`).join("");
  o+=`<div class="sidel">Esami</div>`+EXORD.map(k=>{const on=inEx&&EX===k,opn=isOpen("side-"+k,on);const sc=withExam(k,overall);return `<div class="exrow"><button data-go="${k}" class="exb${on?" on":""}"><span class="ic">${EXAMS[k].ic}</span>${ename(k)}<span class="pct">${sc}%</span></button>${`<button class="sfold${opn?" open":""}" data-sfold="${k}" data-on="${on?1:0}" aria-label="Apri o chiudi le sezioni di ${ename(k)}" aria-expanded="${opn}"><span class="chev"></span></button>`}</div>${opn?`<div class="subnav">${withExam(k,()=>exSects().map(([s,ic,t])=>{const act=on&&((view==="ex:"+s)||(s==="arg"&&view==="arg"));return `<button data-go="${k}${s?"/"+s:""}" class="${act?"on":""}"><span class="ic">${ic}</span>${t}${s==="test"&&!S.pt?'<span class="n">1°</span>':""}${s==="sim"&&S.run?'<span class="n">⏱</span>':""}</button>`;}).join(""))}</div>`:""}`;}).join("");
  const cur=PLAT.find(x=>x[0]===view);const where=exView()?`${E.ic} ${esc(ename(EX))}${curT?" · "+esc(TP[curT].t):""}`:cur?`${cur[1]} ${cur[2]}`:"";
  const mo=isOpen("side-menu",false);$("side").innerHTML=`<button class="menutog" data-mtog aria-expanded="${mo}"><span class="ic">${mo?"✕":"☰"}</span><span class="grow">${mo?"Chiudi il menu":"Menu"}<small>${where}</small></span></button>`+o;$("side").classList.toggle("mclosed",!mo);}
function render(){RUN.clear();clearInterval(simTimer);side();const m=$("main");const v=view;
  let h;if(v==="home")h=vHub();else if(v==="regole")h=vRegole();else if(v==="fonti")h=vFonti();else if(v==="prog")h=vProg();else if(v==="installa")h=vInstalla();else if(v==="novita")h=vNovita();else if(v==="guida")h=vGuida();else if(v==="cerca")h=vCerca();
  else if(curT)h=vTopic(curT);else h=({"ex:":vHome,"ex:test":vTest,"ex:arg":vArg,"ex:es":vEs,"ex:sim":vSim,"ex:form":vForm,"ex:info":vInfo,"ex:storico":vStorico}[v]||vHome)();
  m.innerHTML=h+'<p class="saved" id="fzSaved"></p>';paintSaved();bind();applyBg();window.scrollTo(0,0);if(v==="cerca"){const i=$("srch");if(i&&!QS_)setTimeout(()=>i.focus(),50);}}
const exHead=()=>`<p class="crumb"><button class="btn sm" data-go="home">‹ Semestre filtro</button> <span class="lbl">${E.ic} ${esc(E.t)}</span></p>`;

/* ----- Piattaforma ----- */
function vHub(){const d1=daysTo(EXAM1),d2=daysTo(EXAM2);
  let o=`<h1>🩺 Semestre filtro</h1><p class="sub">Medicina e Chirurgia UPO (Novara / Alessandria) · a.a. 2026/2027 · tre esami nazionali da 31 domande, stesso giorno e stessa ora in tutta Italia.</p>${newsBanner()}<button class="newsbtn guidabtn" data-go="guida"><span class="nb-ic">ℹ️</span><span class="grow"><b>Che cosa fa questa app</b><small>In breve: come ti aiuta a preparare i tre esami</small></span><span class="chev r"></span></button>
  <div class="kpi kpi-home"><div><b>${d1>=0?d1:"—"}</b><span>giorni al 1° appello · gio 10 dic, ore 11</span></div><div><b>${d2>=0?d2:"—"}</b><span>giorni al 2° appello · lun 11 gen, ore 11</span></div><div><b>3 × 6 CFU</b><span>Fisica · Chimica · Biologia</span></div><div><b>18/30</b><span>soglia per superare ogni esame</span></div></div>`;
  o+=`<div class="grid">`+EXORD.map(k=>{const s=withExam(k,summary),X=EXAMS[k];return `<div class="card excard" style="--uc:var(${X.col})"><h3><span class="ubadge" style="--uc:var(${X.col})">${X.ic}</span>${esc(ename(k))}${X.ready?"":'<span class="pill soon">in costruzione</span>'}</h3>
   <div class="hero"><div class="ring sm" style="--p:${s.overall};--rc:var(${X.col})"><b>${s.overall}%</b></div><div class="lbl">${X.ready?`${s.studied}/${s.topics} argomenti studiati · ${s.week} esercizi in 7 giorni${s.pt?`<br>Test d'ingresso ${s.pt.score}/${s.pt.n} (${s.pt.lev})`:"<br>Test d'ingresso da fare"}${s.sim?`<br>Ultima simulazione: <b>${s.sim.lab||F2(s.sim.pts,1)+"/31"}</b>`:""}`:`Programma ufficiale con ${s.topics} argomenti e autovalutazione. Spiegazioni, esercizi e simulazioni in arrivo.`}</div></div>
   ${s.next?`<p class="lbl" style="margin:10px 0 0">Prossimo: <b>${esc(s.next.t)}</b></p>`:""}<div class="btns"><button class="btn ${X.ready?"pri":""}" data-go="${k}">Apri ${esc(ename(k))}</button>${X.ready&&!s.pt&&X.pt.length?`<button class="btn" data-go="${k}/test">Test d'ingresso</button>`:""}</div></div>`;}).join("")+`</div>`;
  o+=`<h2>Come si entra</h2><div class="card"><p style="margin-top:0">La graduatoria nazionale ha tre sezioni: prima chi ha superato <b>tutti e tre</b> gli esami, poi chi ne ha superati due, poi chi ne ha superato uno; dentro ogni sezione conta il punteggio totale (massimo 93). Chi è in posizione utile ma ha uno o due esami mancanti li recupera nella sede assegnata prima del 2° semestre.</p>
   <p class="lbl" style="margin:0">Strategia: arrivare a 18 in tutti e tre conta più di un voto altissimo in uno solo. Nel 2025 la Fisica è stata l'ostacolo principale, per questo è la prima materia completa dell'app.</p></div>
   <h2>Settimana tipo</h2><div class="card"><table class="t"><tr><th>Giorno</th><th>Studio</th><th>Verifica</th></tr>
   <tr><td>Lunedì</td><td>Fisica: argomento del piano + Biologia</td><td>10 esercizi</td></tr><tr><td>Martedì</td><td>Chimica + Fisica (esercizi)</td><td>esercizi misti</td></tr><tr><td>Mercoledì</td><td>Biologia + Chimica</td><td>completamenti</td></tr><tr><td>Giovedì</td><td>Fisica: nuovo argomento + animazioni</td><td>10 esercizi</td></tr><tr><td>Venerdì</td><td>Chimica + Biologia</td><td>ripasso errori</td></tr><tr><td>Sabato</td><td>Simulazione a tempo (da novembre: una materia a turno)</td><td>analisi errori</td></tr><tr><td>Domenica</td><td>Ripasso leggero</td><td>piano della settimana</td></tr></table>
   <p class="lbl" style="margin:8px 0 0">Ogni giorno: 10 minuti di richiamo a memoria, studio di un argomento, esercizi senza guardare le soluzioni, correzione. Gli errori si ripetono dopo 1, 3 e 7 giorni.</p></div>`;
  return o;}

/* ----- Percorso dell'esame ----- */
function vHome(){const ov=overall(),gf=E.ready&&S.goal&&S.goal.t.find(t=>!goalOK(t)),nt=gf&&TP[gf]?TP[gf]:nextTopic(),ls=S.sims[S.sims.length-1],t=today(),pl=plan();
  let o=exHead()+`<h1>${E.ic} ${esc(E.t)}</h1><p class="sub">Programma ministeriale 2026/27 (syllabus MUR, 6 CFU) · ${UNITS.length} unità · ${TOPICS.length} argomenti${QB.length?` · ${QB.length} esercizi`:""}.</p>`;
  if(!E.ready)o+=`<div class="note">🚧 <b>In costruzione.</b> Per ora trovi il programma ufficiale completo, diviso in unità e argomenti, con l'autovalutazione (segna quanto conosci ogni argomento) e il piano di studio. Spiegazioni, animazioni, esercizi e simulazioni arriveranno con lo stesso schema di Fisica.</div>`;
  o+=`<div class="kpi"><div><b>${TOPICS.filter(x=>(S.tp[x.id]||{}).st).length}/${TOPICS.length}</b><span>argomenti segnati «studiato»</span></div><div><b>${ov}%</b><span>preparazione (esercizi giusti + argomenti studiati)</span></div>${QB.length?`<div><b>${ls?F2(sim31(ls),1):"—"}</b><span>ultima simulazione (su 31${ls&&simN(ls)!==31?", in proporzione":""})</span></div>`:""}</div>`;
  if(E.ready&&(S.hist.length||S.goal))o+=goalHTML(true);
  if(PT.length&&!S.pt)o+=`<div class="card" style="border-color:var(--accent)"><h3>🧭 Inizia da qui: test d'ingresso</h3><p class="lead" style="margin:0 0 6px">${Math.min(PT.length,UNITS.length*2)} domande, circa 10 minuti. Serve a capire da quale base parti e a costruire il piano di studio su misura fino al 10 dicembre.</p><div class="btns"><button class="btn pri" data-go="${EX}/test">Fai il test d'ingresso</button></div></div>`;
  o+=`<div class="grid"><div class="card"><h3>📊 Preparazione</h3><div class="hero"><div class="ring" style="--p:${ov}"><b>${ov}%</b></div><div class="lbl">Media pesata delle unità, con il peso che hanno nella prova (31 domande). ${E.ready?"Sale studiando gli argomenti e rispondendo bene agli esercizi.":"Per ora si basa sulla tua autovalutazione."}${S.pt?`<br>Test d'ingresso: <b>${S.pt.score}/${ptSel(S.pt).length}</b> · livello <b>${S.pt.lev}</b>.`:""}</div></div></div>`;
  o+=`<div class="card"><h3>🎯 Oggi ti consiglio</h3>${nt?`<div class="row"><span class="ubadge" style="--uc:var(--${nt.u.replace(/^[cb]/,"u")})">${UN[nt.u].ic}</span><div class="grow"><b>${esc(nt.t)}</b><small>${esc(UN[nt.u].t)} · ${stLab(tScore(nt.id))[0]}</small></div></div><div class="btns"><button class="btn pri" data-go="${EX}/t/${nt.id}">${E.ready?"Studia l'argomento":"Apri il programma"}</button>${hasQ(nt.id)?`<button class="btn" data-pr="t:${nt.id}">Solo esercizi</button>`:""}</div>`:`<p class="empty">Tutti gli argomenti sono padroneggiati: fai simulazioni complete.</p>`}</div></div>`;
  o+=`<h2>Unità del programma</h2>${UNITS.map(u=>{const sc=uScore(u.id),l=ptLevel(u.id),uc=u.id.replace(/^[cb]/,"u");return fold("home-"+EX+"-"+u.id,`<span class="ubadge" style="--uc:var(--${uc})">${u.ic}</span><div class="grow"><b>${esc(u.t)}</b><small>${u.cfu.toLocaleString("it-IT")} CFU · circa ${u.q} domande su 31 (stima da CFU e prove 2025)${l!=null?` · base: <span class="lvl l${l}">${["da costruire","da rinforzare","buona"][l]}</span>`:""}</small></div><div class="mbar"><div class="bar"><i style="width:${sc}%;background:var(--${uc})"></i></div></div><b class="pctb">${sc}%</b>`,TOPICS.filter(t=>t.u===u.id).map(t=>topicRow(t,uc)).join("")+(QB.some(q=>q.u===u.id)?`<div class="btns"><button class="btn sm" data-pr="u:${u.id}">✏️ 10 esercizi dell'unità</button></div>`:""),false,"ufold",uc);}).join("")}`;
  o+=`<h2>Piano di studio</h2><div class="card"><div class="plan">${pl.map(x=>{const now=t>=x.a&&t<=x.b;return `<div class="pstep${now?" now":""}"><span class="d">${x.a===x.b?fmtD(x.a,{weekday:"short",day:"numeric",month:"short"}):fmtD(x.a)+" – "+fmtD(x.b)}</span><span>${x.u?`${x.u.ic} <b>${esc(x.u.t)}</b> <span class="lbl">· ${uScore(x.u.id)}%</span>`:x.ex?`<b>🎓 ${x.x}</b>`:`📝 ${x.x}`}${now?' <span class="pill acc">adesso</span>':""}</span></div>`;}).join("")}</div><p class="lbl" style="margin:8px 0 0">${S.pt?"I giorni per unità tengono conto del peso in CFU, del test d'ingresso e dei progressi: il piano si aggiorna da solo.":"Il piano si adatta ai CFU e ai progressi"+(PT.length?"; diventa su misura dopo il test d'ingresso.":".")} Le lezioni UPO da ottobre sono online (Zoom/DIR): segui qui l'argomento della settimana.</p></div>`;
  return o;}

/* ----- Test d'ingresso ----- */
function vTest(){const head=exHead();if(S.pt&&!PTA){const p=S.pt;let o=head+`<h1>🧭 Test d'ingresso · ${esc(ename(EX))}</h1><p class="sub">Fatto ${artD(p.date)}${fmtD(p.date,{day:"numeric",month:"long"})}.</p><div class="grid"><div class="card"><h3>Risultato</h3><div class="big">${p.score}/${ptSel(p).length}</div><p class="lbl">Livello di partenza: <b>${p.lev}</b>${(p.school||S.school)?` · scuola: ${esc(p.school||S.school)}`:""}</p><p>${levText(p.lev)}</p><div class="btns"><button class="btn pri" data-go="${EX}">Vedi il piano</button><button class="btn" id="ptRedo">Rifai il test</button></div></div>`;
  o+=`<div class="card"><h3>Base per unità</h3>${UNITS.map(u=>{const r=p.unit[u.id]||[0,2];return `<div class="row"><span class="ubadge" style="--uc:var(--${u.id.replace(/^[cb]/,"u")})">${u.ic}</span><div class="grow">${esc(u.t)}</div><b style="margin-right:8px;font-variant-numeric:tabular-nums">${r[0]}/${r[1]}</b><span class="lvl l${r[0]}">${["Da costruire","Da rinforzare","Buona"][r[0]]}</span></div>`;}).join("")}</div></div>`;return o+ptReview(p);}
/* analisi degli errori del test d'ingresso: risposta data, perché è sbagliata, risposta giusta e perché, argomento da ripassare */
function ptReview(p){if(!p.ans)return `<div class="card"><h3>🔍 Errori e perché</h3><p style="margin:0">Questo test è stato fatto con una versione precedente dell'app, che non salvava le risposte. Tocca «Rifai il test»: alla fine troverai ogni errore spiegato.</p></div>`;
  const it=ptSel(p).map((pi,i)=>{const q=PT[pi],c=p.ans[i],ok=c===q.o[q.a],ci=c==null?-1:q.o.indexOf(c);return {q,i,c,ok,ci};}),bad=it.filter(x=>!x.ok),good=it.filter(x=>x.ok),nb=bad.filter(x=>x.c==null).length;
  const card=(x,open)=>{const q=x.q,tp=q.t&&TP[q.t];return `<div class="ptr${x.ok?" ok":""}"><div class="qh"><span class="qn">${x.i+1}.</span><div class="qt">${esc(q.q)} <span class="pill" style="font-size:11px">${UN[q.u].ic} ${esc(UN[q.u].t)}</span></div></div>
   ${x.ok?"":x.c==null?`<p class="ptl no">➖ Non hai risposto.</p>`:`<p class="ptl no">✗ La tua risposta: <b>${esc(x.c)}</b></p>${q.e&&q.e[x.ci]?`<p class="ptw"><b>Perché è sbagliata:</b> ${esc(q.e[x.ci])}</p>`:""}`}
   <p class="ptl si">✓ Risposta giusta: <b>${esc(q.o[q.a])}</b></p>${q.s?`<p class="ptw"><b>Perché:</b> ${esc(q.s)}</p>`:""}
   ${tp?`<div class="btns" style="margin-top:6px"><button class="btn sm${x.ok?"":" pri"}" data-go="${EX}/t/${q.t}">📚 Ripassa: ${esc(tp.t)}</button></div>`:""}</div>`;};
  const tps=[...new Set(bad.map(x=>x.q.t).filter(t=>t&&TP[t]))];
  return `<div class="card"><h3>🔍 Errori e perché</h3>${bad.length?`<p style="margin:0 0 10px">${bad.length-nb?`<b>${bad.length-nb}</b> ${bad.length-nb===1?"risposta sbagliata":"risposte sbagliate"}`:""}${bad.length-nb&&nb?" e ":""}${nb?`<b>${nb}</b> senza risposta`:""}. Per ognuna trovi il ragionamento che porta all'errore, la risposta giusta e l'argomento da ripassare.</p>
   ${tps.length?`<p class="lbl" style="margin:0 0 10px">Da ripassare per primi: ${tps.map(t=>`<button class="lnk" data-go="${EX}/t/${t}">${esc(TP[t].t)}</button>`).join(" · ")}</p>`:""}${bad.map(x=>card(x)).join("")}`:`<p style="margin:0">Nessun errore: ottima base di partenza! Le spiegazioni delle risposte sono qui sotto.</p>`}
   ${good.length?`<details class="ptgood"><summary>✓ Risposte giuste (${good.length}): rivedi perché</summary>${good.map(x=>card(x)).join("")}</details>`:""}</div>`;}
  PTA=PTA||(S.ptDraft&&S.ptDraft.a?{a:Object.assign({},S.ptDraft.a),school:S.ptDraft.school||S.school||Rt.school,sel:S.ptDraft.sel||ptSel(null),seed:S.ptDraft.seed||"d"}:newPTA());const TL=PTA.sel.map(pi=>PT[pi]);
  return head+`<h1>🧭 Test d'ingresso · ${esc(ename(EX))}</h1><p class="sub">${TL.length} domande di livello scuola superiore, 2 per ogni unità, scelte ogni volta in modo diverso tra ${PT.length}. Non conta per il voto: serve a capire da dove partire. Rispondi d'istinto; se non sai, lascia vuoto.</p>
  <div class="card"><h3>Che scuola superiore hai fatto?</h3><div class="segc" id="ptSchool">${SCHOOLS.map(s=>`<button type="button" class="${PTA.school===s?"on":""}">${s}</button>`).join("")}</div></div>
  <div class="card">${TL.map((q,i)=>`<div class="q" data-pt="${i}"><div class="qh"><span class="qn">${i+1}.</span><div class="qt">${esc(q.q)} <span class="pill" style="font-size:11px">${UN[q.u].ic} ${esc(UN[q.u].t)}</span></div></div><div class="opts">${optsHTML(q,PTA.seed,PTA.a[i])}</div></div>`).join("")}
  <div class="btns"><button class="btn pri" id="ptDone">Vedi il risultato</button></div></div>`;}
/* test d'ingresso: 2 domande per unità scelte dal gruppo, evitando quelle del test precedente e le più viste */
const ptSel=p=>p&&p.sel?p.sel:PT.slice(0,14).map((_,i)=>i);
/* ogni test d'ingresso è diverso: per ogni unità 2 domande tra 6, preferendo quelle viste meno, con una parte casuale
   (le combinazioni possibili sono milioni) e senza mai ripetere esattamente un test già fatto */
function ptPick(){const last=new Set(S.pt?ptSel(S.pt):[]),seen=S.ptSeen||{},used=new Set((S.ptSets||[]));let out=[];
  for(let tr=0;tr<30;tr++){out=[];UNITS.forEach(u=>{PT.map((q,i)=>[q,i]).filter(([q])=>q.u===u.id).map(([q,i])=>[i,(last.has(i)?6:0)+(seen[i]||0)*2+Math.random()*7]).sort((a,b)=>a[1]-b[1]).slice(0,2).forEach(x=>out.push(x[0]));});
    if(!used.has(out.slice().sort((a,b)=>a-b).join(",")))break;}return out;}
function newPTA(){return {a:{},school:S.school||Rt.school,sel:ptPick(),seed:Date.now().toString(36)};}
function levText(l){return l==="avanzato"?"Hai basi solide: puoi andare veloce sulle parti note e concentrarti sulle unità che pesano di più nella prova e sulle novità 2026. Allenati presto sui tempi.":l==="intermedio"?"Basi discrete con qualche lacuna: segui il piano unità per unità, guarda le animazioni e fai gli esercizi di ogni argomento prima delle simulazioni.":"Si parte dalle basi: è normale. Segui il piano dall'inizio, usa molto le animazioni e il formulario, e fai pochi esercizi ma tutti i giorni.";}

/* ----- Argomenti / programma ----- */
const SELF=[["Non ancora","Da studiare"],["In parte","Lo conosco in parte"],["Bene","Lo so bene"]];
function vArg(){const fu=argU;let o=exHead()+`<h1>📚 ${E.ready?"Argomenti":"Programma"} · ${esc(ename(EX))}</h1><p class="sub">Il programma ufficiale 2026/27 (syllabus MUR, 6 CFU) diviso nelle ${UNITS.length} unità didattiche. ${E.ready?"Ogni argomento: concetti chiave, formule, animazione, trappole d'esame ed esercizi.":"Per ogni argomento: le voci del syllabus e la tua autovalutazione."} <a href="${E.syl}" target="_blank" rel="noopener">Syllabus ufficiale (PDF)</a></p>`;
  o+=`<div class="btns" style="margin:-4px 0 10px"><button class="btn sm" data-fall="t"><span class="chev" aria-hidden="true"></span> Apri / chiudi tutte</button></div>`;
  o+=UNITS.map(u=>{const uc=u.id.replace(/^[cb]/,"u"),k="arg-"+EX+"-"+u.id;if(argU===u.id)setFold(k,1);const nt=TOPICS.filter(t=>t.u===u.id);return `<div id="u-${u.id}">${fold(k,`<span class="ubadge" style="--uc:var(--${uc})">${u.ic}</span><div class="grow"><b>${esc(u.t)}</b><small>${u.cfu.toLocaleString("it-IT")} CFU · ${nt.length} argomenti · ${QB.filter(q=>q.u===u.id).length} domande</small></div><div class="mbar"><div class="bar"><i style="width:${uScore(u.id)}%;background:var(--${uc})"></i></div></div><b class="pctb">${uScore(u.id)}%</b>`,`<div class="tlist">${nt.map(t=>topicRow(t,uc)).join("")}</div>${uffUnit(EX,u.id)}${QB.some(q=>q.u===u.id)?`<div class="btns"><button class="btn sm" data-pr="u:${u.id}">✏️ Esercizi dell'unità</button></div>`:""}`,false,"ufold",uc)}</div>`;}).join("");
  return o;}
/* riga di un argomento: emoji, titolo, contenuti, stato */
function topicRow(t,uc){const sc=tScore(t.id),lb=stLab(sc),nq=QB.filter(q=>q.t===t.id).length,s=S.tp[t.id]||{};return `<button class="trow" data-go="${EX}/t/${t.id}"><span class="tic">${tic(t)}</span><div class="grow"><b>${esc(t.t)}</b>${t.tag?`<span class="tag26">${esc(t.tag)}</span>`:""}<small>${t.anim?"🎞️ animazione · ":""}${nq?nq+" esercizi":"programma"+(s.self?" · "+SELF[s.self-1][1].toLowerCase():"")}${(GEN[EX]||[]).some(G=>G.t===t.id)?" · 🎲 varianti":""}${s.st?" · ✓ studiato":""}</small></div><span class="pill ${lb[1]}">${lb[0]}</span><div class="mbar"><div class="bar"><i style="width:${sc}%;background:var(--${uc})"></i></div></div></button>`;}
function vTopic(id){const t=TP[id],u=UN[t.u],s=S.tp[id]||{},qs=QB.filter(q=>q.t===id),i=TOPICS.indexOf(t),prev=TOPICS[i-1],next=TOPICS[i+1];
  if(!s.seen){S.tp[id]=Object.assign(s,{seen:today()});save();}
  let o=`<p class="crumb"><button class="btn sm" data-go="${EX}/arg">‹ ${E.ready?"Argomenti":"Programma"}</button> <span class="lbl">${E.ic} ${esc(ename(EX))} · ${u.ic} ${esc(u.t)}</span></p><h1><span class="tic big">${tic(t)}</span>${esc(t.t)}${t.tag?`<span class="tag26">${esc(t.tag)}</span>`:""}</h1><p class="sub" id="tSub">${stLab(tScore(id))[0]} · ${tScore(id)}%</p>`;
  o+=`<div class="btns" style="margin:-4px 0 10px"><button class="btn sm" data-fall="t"><span class="chev" aria-hidden="true"></span> Apri / chiudi tutto</button></div>`;
  if(t.breve)o+=fold("tp-breve",`<h3>💡 In breve</h3>`,`<ul class="breve">${t.breve.map(b=>`<li>${esc(b)}</li>`).join("")}</ul>`,true);
  if(t.syl)o+=fold("tp-syl",`<h3>📋 Dal syllabus ufficiale</h3>`,`<ul class="breve">${t.syl.map(b=>`<li>${esc(b)}</li>`).join("")}</ul>${t.sp?"":`<p class="lbl" style="margin:8px 0 0">Spiegazioni, animazioni ed esercizi di questo argomento sono in preparazione.</p>`}`,!t.sp);
  if(t.sp)o+=fold("tp-sp",`<h3>📖 Spiegazione <span class="lbl">· ${t.sp.length} paragrafi</span></h3>`,t.sp.map(p=>`<p>${esc(p)}</p>`).join(""),true,"expl");
  if(t.anim){const cc=(AN[t.anim]&&AN[t.anim].c)||[],sl=cc.some(c=>!c.seg),sg=cc.some(c=>c.seg);o+=fold("tp-anim",`<h3>🎞️ Prova tu</h3>`,`<p class="lbl" style="margin:0">${sl&&sg?"Muovi i cursori e tocca i pulsanti: guarda che cosa cambia.":sl?"Muovi i cursori e guarda che cosa cambia.":sg?"Tocca i pulsanti e guarda che cosa cambia.":"Guarda l'animazione: usa Pausa e Ricomincia per seguirla passo passo."}</p><div id="animBox"></div>`,true);}
  if(t.es&&t.es.length)o+=fold("tp-es",`<h3>🧮 Esempi svolti <span class="lbl">· ${t.es.length}</span></h3>`,`${t.es.map((e,j)=>`<details class="esv"${j?"":" open"}><summary><b>Esempio ${j+1}.</b> ${esc(e.q)}</summary><ol>${e.p.map(x=>`<li>${esc(x)}</li>`).join("")}</ol><p class="esr">➜ ${esc(e.r)}</p></details>`).join("")}<p class="lbl" style="margin:8px 0 0">Prova a risolverli da solo prima di aprire i passaggi.</p>`,true);
  if(t.form)o+=fold("tp-form",`<h3>${E.formLab||"📐 Formule"}</h3>`,`${t.form.map(f=>`<div class="formula">${esc(f[0])}${f[1]?`<small>${esc(f[1])}</small>`:""}</div>`).join("")}${t.trap?`<div class="trap">⚠️ <b>Trappola d'esame:</b> ${esc(t.trap)}</div>`:""}`,true);
  if(t.med)o+=fold("tp-med",`<h3>🩺 In medicina</h3>`,`<p style="margin:0">${esc(t.med)}</p>`,true,"med");
  if(!qs.length)o+=`<div class="card"><h3>🙋 Quanto lo conosci?</h3><div class="segc" id="selfEv">${SELF.map((x,j)=>`<button type="button" data-v="${j+1}" class="${s.self===j+1?"on":""}">${x[1]}</button>`).join("")}</div><p class="lbl" style="margin:8px 0 0">La tua risposta aggiorna la percentuale dell'unità e il piano di studio.</p></div>`;
  else o+=`<div class="card"><h3>✏️ Esercizi (${qs.length})</h3><div class="btns" style="margin:0"><button class="btn pri sm" data-pr="t:${id}">Allenamento: 10 domande ›</button>${(GEN[EX]||[]).some(G=>G.t===id)?`<button class="btn sm" data-pr="g:${id}">🎲 Varianti con numeri nuovi</button>`:""}</div></div>`+fold("tp-q",`<h3>📝 Tutte le domande dell'argomento <span class="lbl">· ${qs.length}</span></h3>`,qs.map((q,j)=>qHTML(q,j+1,"tp")).join(""),false);
  o+=`<div class="btns" style="justify-content:space-between"><span>${prev?`<button class="btn" data-go="${EX}/t/${prev.id}">‹ ${esc(prev.t)}</button>`:""}</span><button class="btn ${s.st?"ok":"pri"}" id="tStudied">${s.st?"✓ Studiato":"Segna come studiato"}</button><span>${next?`<button class="btn" data-go="${EX}/t/${next.id}">${esc(next.t)} ›</button>`:""}</span></div>`;
  return o;}

/* ----- Esercizi ----- */
/* domande sempre diverse: prima quelle mai viste, poi le meno viste; si evitano quelle delle ultime prove */
function recentIds(n){const st=new Set();S.hist.slice(-n).forEach(h=>h.items.forEach(it=>{if(it.id)st.add(it.id);}));return st;}
function pickFresh(arr,n,avoid){const av=avoid||recentIds(3),seen=q=>{const x=S.qs[q.id];return x?(x.ok||0)+(x.ko||0):0;};
  return arr.map(q=>[q,(av.has(q.id)?1000:0)+seen(q)*10+Math.random()*9]).sort((a,b)=>a[1]-b[1]).slice(0,n).map(x=>x[0]).sort(()=>Math.random()-.5);}
const realTag=q=>q&&q.r?`<span class="realb">📌 Prova reale · ${REAL_LAB[q.r]}, domanda ${q.rn}</span>`:q&&q.gen?`<span class="realb genb">🎲 Numeri nuovi a ogni prova</span>`:"";
/* calcoli a numeri variabili sbagliati l'ultima volta (chiave «esame~tipo» in S.qs come «g~esame~tipo») */
const genErrKeys=()=>Object.keys(S.qs).filter(k=>k.startsWith("g~"+EX+"~")&&S.qs[k].last===0).map(k=>k.slice(2));
/* inserisce n domande generate (numeri sempre nuovi) al posto di altrettante della lista */
function withGen(list,n,filt){const g=genFor(EX,n,filt);if(!g.length)return list;const out=list.slice(0,Math.max(0,list.length-g.length)).concat(g);return out.sort(()=>Math.random()-.5);}
function pick(arr,n){const a=arr.slice();for(let i=a.length-1;i>0;i--){const j=Math.random()*(i+1)|0;[a[i],a[j]]=[a[j],a[i]];}return a.slice(0,n);}
function startPR(mode){let list,lab;
  if(mode.startsWith("t:")){const id=mode.slice(2);list=withGen(pickFresh(QB.filter(q=>q.t===id),10),2,G=>G.t===id);lab=TP[id].t;}
  else if(mode.startsWith("g:")){const id=mode.slice(2);list=genFor(EX,5,G=>G.t===id);lab="Varianti con numeri nuovi: "+TP[id].t;}
  else if(mode==="gen"){list=genFor(EX,10);lab="🎲 Esercizi con numeri sempre nuovi";}
  else if(mode.startsWith("u:")){const u=mode.slice(2);list=withGen(pickFresh(QB.filter(q=>q.u===u),10),2,(G,t)=>t&&t.u===u);lab=UN[u].t;}
  else if(mode.startsWith("et:")){const t=mode.slice(3),w=QB.filter(q=>q.t===t&&S.qs[q.id]&&S.qs[q.id].last===0);list=w.length?pick(w,w.length):pickFresh(QB.filter(q=>q.t===t),6);lab=(w.length?"Errori di: ":"Esercizi su: ")+TP[t].t;}
  else if(mode.startsWith("ids:")){list=mode.slice(4).split(",").map(id=>QI[id]).filter(Boolean);lab="Rifai gli errori della serie";}
  else if(mode==="err"){const gk=genErrKeys();list=pick(QB.filter(q=>S.qs[q.id]&&S.qs[q.id].last===0),10);if(list.length<10&&gk.length)list=list.concat(gk.slice(0,10-list.length).map(k=>genFor(EX,1,G=>EX+"~"+G.g===k)[0]).filter(Boolean));lab="Ripasso degli errori";}
  else if(mode==="weak"){const w=TOPICS.filter(t=>hasQ(t.id)).sort((a,b)=>tScore(a.id)-tScore(b.id)).slice(0,5).map(t=>t.id);list=withGen(pickFresh(QB.filter(q=>w.includes(q.t)),10),2,G=>w.includes(G.t));lab="Punti deboli";}
  else if(mode==="real"){list=pickFresh(QB.filter(q=>q.r),10);lab="Domande delle prove reali 2025";}
  else{list=withGen(pickFresh(QB,10),2);lab="Misto";}
  if(!list.length){toast("Nessuna domanda per questa scelta");return;}PR={lab,list,i:0,ok:0,seed:Date.now().toString(36),mode,res:[]};prSave();curT=null;view="ex:es";if(location.hash!=="#"+EX+"/es")history.replaceState(null,"","#"+EX+"/es");render();}
/* la serie in corso resta salvata: se si chiude l'app o si cambia pagina si riprende da dove si era */
function prSave(){S.prDraft=PR&&PR.i<PR.list.length?{lab:PR.lab,ids:PR.list.map(q=>q.id),i:PR.i,ok:PR.ok,seed:PR.seed,mode:PR.mode,res:PR.res||[],h:PR.h||null}:null;save();}
function prResume(){const d=S.prDraft;if(!d)return false;const list=d.ids.map(id=>QI[id]).filter(Boolean);if(!list.length){S.prDraft=null;return false;}
  PR={lab:d.lab,list,i:Math.min(d.i,list.length),ok:d.ok,seed:d.seed,mode:d.mode,res:d.res||[],h:d.h};return true;}
function prEnd(r){const ko=(r.res||[]).filter(x=>!x.ok).map(x=>QI[x.id]).filter(Boolean),tt=r.mode&&/^(t|g|et):/.test(r.mode)?r.mode.split(":")[1]:null;
  return `<h1>✏️ ${esc(r.lab)}</h1><div class="card"><div class="big">${r.ok}/${r.list.length}</div><p class="lbl">risposte giuste${ko.length?` · ${ko.length} da rivedere qui sotto`:""}</p>
   <div class="btns">${tt&&TP[tt]?`<button class="btn pri" data-go="${EX}/t/${tt}">‹ Torna all'argomento</button>`:""}${ko.filter(q=>!q.gen).length?`<button class="btn ${tt?"":"pri"}" data-pr="ids:${ko.filter(q=>!q.gen).map(q=>q.id).join(",")}">🎯 Rifai questi errori</button>`:""}<button class="btn" data-pr="weak">Punti deboli</button><button class="btn" data-go="${EX}/es">Altri esercizi</button></div></div>
   ${ko.length?`<h2>Da rivedere</h2><div class="card">${ko.map(q=>{const x=r.res.find(y=>y.id===q.id);return itemHTML(q,x?x.a:null,false)+`<div class="btns" style="margin:-4px 0 8px"><button class="btn sm" data-go="${EX}/t/${q.t}">📖 ${esc(TP[q.t].t)}</button></div>`;}).join("")}</div>`:""}`;}
function vEs(){const h=exHead();if(!PR&&S.prDraft&&S.prDraft.auto)prResume();if(PR){const q=PR.list[PR.i];if(!q){const r=PR;PR=null;S.prDraft=null;save();return h+prEnd(r);}
   return h+`<h1>✏️ ${esc(PR.lab)}</h1><p class="sub">Domanda ${PR.i+1} di ${PR.list.length} · ${PR.ok} giuste</p><div class="bar" style="margin-bottom:12px"><i style="width:${PR.i/PR.list.length*100}%"></i></div><div class="card" id="prBox"><p class="lbl" style="margin:0 0 6px">${UN[q.u].ic} ${esc(TP[q.t].t)} · ${q.k==="m"?"risposta multipla":"completamento"}</p>${qHTML(q,null,"pr")}<div class="btns"><button class="btn pri" id="prNext" hidden>Avanti ›</button><button class="btn" id="prStop">Termina</button></div></div>`;}
  const ne=QB.filter(q=>S.qs[q.id]&&S.qs[q.id].last===0).length+genErrKeys().length;
  const dr=S.prDraft;
  return h+`<h1>✏️ Esercizi · ${esc(ename(EX))}</h1>${dr?`<div class="card" style="border-color:var(--accent)"><h3>⏸ Serie interrotta</h3><p style="margin:0">${esc(dr.lab)} · domanda ${Math.min(dr.i+1,dr.ids.length)} di ${dr.ids.length} · ${dr.ok} giuste finora.</p><div class="btns"><button class="btn pri" id="prResume">▶ Riprendi la serie</button><button class="btn" id="prDrop">Lascia perdere</button></div></div>`:""}<p class="sub">Serie da 10 domande con correzione e spiegazione immediata. ${QB.length} domande in stile prova nazionale (numeri semplici, senza calcolatrice).</p>
  <div class="grid"><div class="card"><h3>Scegli come allenarti</h3><div class="btns" style="flex-direction:column;align-items:stretch"><button class="btn pri" data-pr="weak">🎯 Punti deboli</button><button class="btn" data-pr="mix">🔀 Misto su tutto il programma</button>${(GEN[EX]||[]).length?`<button class="btn" data-pr="gen">🎲 Numeri sempre nuovi (${GEN[EX].length} tipi di calcolo)</button>`:""}${QB.some(q=>q.r)?`<button class="btn" data-pr="real">📌 Domande delle prove reali 2025 (${QB.filter(q=>q.r).length})</button>`:""}<button class="btn" data-pr="err"${ne?"":" disabled"}>🔁 Ripassa gli errori (${ne})</button></div></div>
  <div class="card"><h3>Per unità</h3>${UNITS.map(u=>`<button class="trow" data-pr="u:${u.id}"><span class="ubadge" style="--uc:var(--${u.id.replace(/^[cb]/,"u")})">${u.ic}</span><div class="grow">${esc(u.t)}<small>${QB.filter(q=>q.u===u.id).length} domande</small></div><b>${uScore(u.id)}%</b></button>`).join("")}</div></div>`;}

/* ----- Simulazione ----- */
const SIM_MIN=50;
function buildSim(){let mc=[],cp=[];const av=recentIds(2);S.sims.slice(-2).forEach(x=>(x.q||[]).forEach(id=>av.add(id)));UNITS.forEach(u=>{const pc=pickFresh(QB.filter(q=>q.u===u.id&&q.k==="c"),u.cp,av),pm=pickFresh(QB.filter(q=>q.u===u.id&&q.k==="m"),u.q-pc.length,av);
  /* circa una volta su tre, in ogni unità una domanda a risposta multipla diventa una variante con numeri nuovi */
  if(pm.length&&Math.random()<.35){const g=genFor(EX,1,(G,t)=>t&&t.u===u.id);if(g.length)pm[pm.length-1]=g[0];}cp=cp.concat(pc);mc=mc.concat(pm);});return mc.concat(cp).map(q=>q.id);}
function simLeft(){return S.run?Math.max(0,S.run.start+(S.run.min||SIM_MIN)*60e3-Date.now()):0;}
function grade(run){let ok=0,ko=0,om=0;const per={};run.q.forEach((id,i)=>{const q=QI[id],v=run.a[i];if(!q)return;const u=q.u;per[u]=per[u]||[0,0];per[u][1]++;
  if(v==null||v===""){om++;return;}const r=q.k==="m"?v===q.a:cpOK(q,v);if(r){ok++;per[u][0]++;}else ko++;});return{ok,ko,om,pts:Math.round((ok-.1*ko)*10)/10,per};}
function finishSim(auto){const r=S.run;if(!r)return;const g=grade(r);r.q.forEach((id,i)=>{const q=QI[id],v=r.a[i];if(q&&v!=null&&v!=="")rec(q,q.k==="m"?v===q.a:cpOK(q,v));});
  S.sims.push({date:new Date().toISOString(),seed:r.seed||r.start,pts:g.pts,ok:g.ok,ko:g.ko,om:g.om,per:g.per,q:r.q,a:r.a,min:Math.round((Date.now()-r.start)/60e3),real:r.real||null});try{logSim(r,g);}catch(e){}S.run=null;S.goal&&S.goal.t.every(goalOK)||ensureGoal();save();SIMV=S.sims.length-1;if(auto)toast("Tempo scaduto: prova consegnata");render();}
/* numero di domande di una prova (31 per le simulazioni 2026; le prove reali 2025 ricostruite possono averne meno)
   e punteggio riportato su 31 in proporzione, per voto e soglia del 18 */
const simN=s=>(s&&Array.isArray(s.q)&&s.q.length)||31;
const sim31=s=>simN(s)===31?s.pts:Math.round(s.pts*31/simN(s)*10)/10;
const simLab=s=>simN(s)===31?`${F2(s.pts,1)}/31`:`${F2(s.pts,1)}/${simN(s)} (≈ ${F2(sim31(s),1)}/31)`;
function voto(p){return p>30?"30 e lode":p>=18?Math.min(30,Math.round(p))+"/30":"non superato";}
function vSim(){const h=exHead();
  if(S.run){if(simLeft()<=0){setTimeout(()=>finishSim(true),0);return "<p>Consegna…</p>";}const r=S.run,nm=r.q.filter(id=>QI[id]&&QI[id].k==="m").length;
   return `<div id="player"><div class="timer"><span class="clock" id="clock">--:--</span><div class="grow lbl">${E.ic} ${esc(ename(EX))} · ${r.real?`<b>📌 Prova reale, ${REAL_LAB[r.real]}</b> · ${nm} a risposta multipla + ${r.q.length-nm} a completamento (formato 2025)`:"21 a risposta multipla + 10 a completamento"} · +1 giusta, −0,1 sbagliata, 0 omessa. Per togliere una risposta toccala di nuovo.</div><button class="btn pri" id="simEnd">Consegna</button></div>
   <div class="card">${r.q.map((id,i)=>{const q=QI[id];if(!q)return"";const v=r.a[i];const sec=i===0?`<h3>Parte 1 · risposta multipla</h3>`:i===nm?`<h3 style="margin-top:14px">Parte 2 · completamento (una sola parola, in stampatello)</h3>`:"";
    return sec+(q.k==="m"?`<div class="q" data-si="${i}"><div class="qh"><span class="qn">${i+1}.</span><div class="qt">${esc(q.q)}${r.real?"":realTag(q)}</div></div><div class="opts">${optsHTML(q,r.seed||r.start,v)}</div></div>`
     :`<div class="q" data-si="${i}"><div class="qh"><span class="qn">${i+1}.</span><div class="qt">${esc(q.q)}${r.real?"":realTag(q)}</div></div><div class="cpl"><input type="text" autocomplete="off" autocapitalize="characters" spellcheck="false" value="${esc(v||"")}" placeholder="Risposta" aria-label="Risposta ${i+1}"></div></div>`);}).join("")}
   <div class="btns"><button class="btn pri" id="simEnd2">Consegna la prova</button></div></div></div>`;}
  if(SIMV!=null&&S.sims[SIMV]){const s=S.sims[SIMV];const N=simN(s),p31=sim31(s),pass=p31>=18;
   let o=`<p class="crumb"><button class="btn sm" id="simBack">‹ Simulazioni</button> <span class="lbl">${E.ic} ${esc(ename(EX))}</span></p>`+`<h1>⏱️ Risultato ${s.real?"della prova reale · "+REAL_LAB[s.real]:"della simulazione"}</h1><p class="sub">${new Date(s.date).toLocaleString("it-IT",{day:"numeric",month:"long",hour:"2-digit",minute:"2-digit"})} · ${s.min} minuti</p>
   <div class="kpi"><div><b style="color:var(--${pass?"ok":"warn"})">${F2(s.pts,1)}</b><span>punti su ${N} · ${voto(p31)}${N!==31?` (≈ ${F2(p31,1)}/31 in proporzione)`:""}</span></div><div><b>${s.ok}</b><span>giuste (+${s.ok})</span></div><div><b>${s.ko}</b><span>sbagliate (−${F2(s.ko*.1,1)})</span></div><div><b>${s.om}</b><span>omesse (0)</span></div></div>
   <p class="lbl" style="margin:-4px 0 10px">Voto: il punteggio (${F2(p31,1)}) si arrotonda all'intero più vicino; da 18 la prova è superata, oltre 30 vale 30 e lode.</p><div class="card"><h3>Per unità</h3>${N!==31?`<p class="lbl" style="margin-top:0">Questa prova reale, così come è stata ricostruita dalle fonti, ha ${N} domande invece di 31: il voto e la soglia del 18 sono calcolati in proporzione (${F2(s.pts,1)} × 31 / ${N}).</p>`:""}${UNITS.map(u=>{const r=s.per[u.id]||[0,0];return `<div class="row"><span class="ubadge" style="--uc:var(--${u.id.replace(/^[cb]/,"u")})">${u.ic}</span><div class="grow">${esc(u.t)}</div><b>${r[0]}/${r[1]}</b></div>`;}).join("")}${s.om?`<div class="note">💡 Con −0,1 per errore e 5 opzioni, anche una risposta a caso vale in media +0,12 punti: <b>nelle domande a risposta multipla conviene non lasciare vuoti.</b></div>`:""}</div>
   <div class="card"><h3>Correzione</h3>${s.q.map((id,i)=>{const q=QI[id];if(!q)return"";const v=s.a[i],om=v==null||v==="",ok=!om&&(q.k==="m"?v===q.a:cpOK(q,v));
    return `<div class="q"><div class="qh"><span class="qn">${i+1}.</span><div class="qt">${esc(q.q)}${realTag(q)}</div></div><div class="sol">${om?"⚪ Omessa":ok?'<b class="okc">✓ Giusta</b>':'<b class="koc">✗ Sbagliata</b> (hai risposto: '+esc(q.k==="m"?letOf(q,s.seed,v)+") "+q.o[v]:v)+")"} · Risposta: <b>${esc(q.k==="m"?letOf(q,s.seed,q.a)+") "+q.o[q.a]:cpShow(q.a[0]))}</b>. ${esc(q.s)} <button class="lnk" data-go="${EX}/t/${q.t}">Ripassa ›</button></div></div>`;}).join("")}</div>
   <div class="btns"><button class="btn pri" id="simStart">Nuova simulazione</button><button class="btn" id="simBack">Indietro</button></div>`;return o;}
  const best=S.sims.reduce((a,s)=>Math.max(a,sim31(s)),-Infinity);
  return h+`<h1>⏱️ Simulazione · ${esc(ename(EX))}</h1><p class="sub">Stessa struttura della prova nazionale 2026/27: 31 domande (21 a risposta multipla con 5 opzioni + 10 a completamento), 50 minuti, punteggio +1 / −0,1 / 0, sufficienza a 18. Le domande sono distribuite tra le unità in base ai CFU e alle prove 2025.</p>
  <div class="grid"><div class="card"><h3>Pronto?</h3><p>Mettiti in un posto tranquillo, senza calcolatrice né formulario. Il tempo parte quando tocchi il pulsante e continua anche se chiudi l'app: le risposte restano salvate. Ogni simulazione è diversa dalle precedenti: l'app sceglie prima le domande che non hai ancora visto.</p><div class="btns"><button class="btn pri" id="simStart">▶ Inizia la simulazione (50 min)</button></div></div>
  ${["A1","A2"].filter(k=>QB.some(q=>q.r===k)).length?`<div class="card"><h3>📌 Rifai una prova reale</h3><p>Le domande delle prove nazionali davvero svolte nel 2025, nello stesso ordine e con 45 minuti come allora (punteggio 2026: +1 / −0,1 / 0).</p><div class="btns" style="flex-direction:column;align-items:stretch">${["A1","A2"].filter(k=>QB.some(q=>q.r===k)).map(k=>`<button class="btn" data-real="${k}">📌 ${REAL_LAB[k]} · ${QB.filter(q=>q.r===k).length} domande${QB.filter(q=>q.r===k).length!==31?" (ricostruite; voto in proporzione su 31)":""}</button>`).join("")}</div></div>`:""}
  <div class="card"><h3>Le tue simulazioni</h3>${S.sims.length?S.sims.slice().reverse().slice(0,8).map((s,k)=>{const i=S.sims.length-1-k;return `<button class="trow" data-simv="${i}"><div class="grow"><b>${simLab(s)}${s.real?" · 📌 prova reale":""}</b><small>${new Date(s.date).toLocaleDateString("it-IT",{day:"numeric",month:"short"})} · ${s.ok} giuste, ${s.ko} sbagliate, ${s.om} omesse</small></div><span class="pill ${sim31(s)>=18?"ok":"warn"}">${sim31(s)>=18?"superata":"sotto 18"}</span></button>`;}).join("")+`<p class="lbl">Migliore: <b>${F2(best,1)}</b> su 31</p>`:'<p class="empty">Ancora nessuna. Consiglio: la prima dopo aver visto tutte le unità almeno una volta, poi una a settimana; dal 1° dicembre una ogni due giorni.</p>'}</div></div>`;}
function tickSim(){const e=$("clock");if(!e){clearInterval(simTimer);return;}const l=simLeft();const m=Math.floor(l/60e3),s=Math.floor(l%60e3/1e3);e.textContent=pad(m)+":"+pad(s);e.classList.toggle("low",l<5*60e3);if(l<=0){clearInterval(simTimer);finishSim(true);}}

/* ----- Formulario ----- */
function vForm(){let o=exHead()+`<h1>${E.formLab?"📌":"📐"} ${E.formT||"Formulario"} · ${esc(ename(EX))}</h1><p class="sub">${E.formLab?"Gli schemi e le associazioni da sapere a memoria, unità per unità.":"Tutte le formule del programma, unità per unità. All'esame non si porta: ripassale a voce e fai attenzione alle unità di misura."}</p>
  <div class="fgrid">${UNITS.map(u=>`<div class="card"><h3><span class="ubadge" style="--uc:var(--${u.id})">${u.ic}</span>${esc(u.t)}</h3>${TOPICS.filter(t=>t.u===u.id&&t.form).map(t=>t.form.map(f=>`<div class="formula">${esc(f[0])}</div>`).join("")).join("")}</div>`).join("")}</div>`;
  if(EX==="fis")o+=`<div class="card"><h3>🔢 Costanti e valori da sapere</h3><table class="t"><tr><th>Grandezza</th><th>Valore</th></tr>
  <tr><td>Accelerazione di gravità g</td><td>9,8 m/s² (spesso 10 negli esercizi)</td></tr><tr><td>Pressione atmosferica</td><td>1 atm ≈ 1,013·10⁵ Pa ≈ 760 mmHg</td></tr><tr><td>Densità dell'acqua</td><td>1000 kg/m³ = 1 g/cm³</td></tr><tr><td>Calore specifico dell'acqua</td><td>4186 J/(kg·K) ≈ 1 cal/(g·°C)</td></tr><tr><td>Costante dei gas R</td><td>8,31 J/(mol·K)</td></tr><tr><td>Volume molare (0 °C, 1 atm)</td><td>22,4 L</td></tr><tr><td>Velocità del suono in aria</td><td>≈ 340 m/s</td></tr><tr><td>Velocità della luce</td><td>3·10⁸ m/s</td></tr><tr><td>Carica elementare e</td><td>1,6·10⁻¹⁹ C · 1 eV = 1,6·10⁻¹⁹ J</td></tr><tr><td>Costante di Coulomb k</td><td>9·10⁹ N·m²/C²</td></tr><tr><td>Costante di Planck h</td><td>6,6·10⁻³⁴ J·s</td></tr><tr><td>Soglia di udibilità I₀</td><td>10⁻¹² W/m²</td></tr><tr><td>sin 30° · sin 45° · sin 60°</td><td>0,5 · 0,71 · 0,87</td></tr><tr><td>ln 2</td><td>≈ 0,693</td></tr></table></div>`;
  return o;}

/* ----- Storia della prova e syllabus ----- */
const LK=(k,t)=>`<a href="${SRC[k]}" target="_blank" rel="noopener">${t}</a>`;
function vInfo(){let o=exHead()+`<h1>📜 Storia e syllabus · ${esc(ename(EX))}</h1><p class="sub">Che cosa è uscito nel 2025/26 e che cosa chiede il programma 2026/27. La fonte vincolante è il <a href="${E.syl}" target="_blank" rel="noopener">syllabus ufficiale MUR</a>.</p>`;
  o+=`<div class="card"><h3>📊 Risultati 2025/26</h3><p style="margin:0">${esc(E.r25)}</p></div>`;
  if(EX==="fis"){o+=`<div class="card"><h3>📝 Che cosa è uscito nel 2025</h3><ul class="breve"><li><b>1° appello (20 novembre):</b> un esercizio semplice per ogni capitolo. Molla (periodo e costante elastica), lavoro come prodotto scalare, quantità di moto e urto anelastico, moto circolare uniforme; legge di Poiseuille, densità e galleggiamento; gas perfetti, rendimento di Carnot, isocora; V = Q/C, legge di Ohm, resistenze in serie e parallelo, carica in un campo magnetico, indice di rifrazione; λ = v/f, periodo e frequenza, che cosa trasporta un'onda sonora; energia del fotone, campi E e B perpendicolari, lente convergente con immagine reale e ingrandita.</li>
   <li><b>2° appello (10 dicembre):</b> livello medio/medio-difficile. Distribuzione: metodi 5, meccanica 3, fluidi 5, onde 5, termodinamica 6, elettricità e magnetismo 5, radiazioni 2. Usciti: conversioni (velocità, accelerazioni, Pa–atm, litri–dm³–cm³) e grandezze adimensionali; Archimede in tre domande (galleggiamento con carico, frazione immersa), sub a 50 m, numero di Reynolds; decibel e significato di 0 dB, potenza dell'onda al raddoppio della frequenza, Doppler in percentuale, suono nel vuoto; gas reali, energia interna n·c_v·ΔT, capacità termica, entropia, lavoro nell'isobara; equipotenziali di una carica, linee di campo nel condensatore, energia di una carica in una d.d.p., linee di B chiuse; lastra a facce parallele, riflessione totale e fibre ottiche.</li>
   <li>Mai usciti finora: momento angolare, modulo di Young, circuiti RC, legge di Gauss, Biot-Savart, onde stazionarie, leggi di Wien e Stefan-Boltzmann, microscopio.</li></ul><p class="src">Fonti: ${LK("esiti","esiti del 1° appello")} · ${LK("promossi","promossi sui due appelli")} · ${LK("tb2","distribuzione del 2° appello")} · ${LK("tbuddy","argomenti del 2° appello")} · ${LK("tb1","argomenti del 1° appello")} · ${LK("prove","testi delle prove 2025")}</p></div>
   <div class="card"><h3>🔄 Il syllabus 2026/27 (testo ufficiale)</h3><ul class="breve"><li><b>Novità:</b> legge di Lambert-Beer; attività, legge del decadimento radioattivo ed emivita; isotopi e trasformazioni nucleari; distinzione tra radiazioni ionizzanti e non ionizzanti. L'unità 7 si chiama «Fisica delle radiazioni». Ogni unità prevede dal 20 al 30% di esercitazioni.</li>
   <li><b>Attenzione:</b> alcune analisi online danno per tolti argomenti che il testo ufficiale invece contiene: quantità di moto, impulso e conservazione; centro di massa e corpo rigido; oscillatore armonico, sovrapposizione e interferenza; calorimetria; trasformazioni reversibili e irreversibili; condensatori in serie e in parallelo; induzione elettromagnetica (Faraday-Neumann-Lenz); tensione superficiale e capillarità. <b>L'app segue il testo ufficiale.</b></li>
   <li><b>Non più nel testo 2026:</b> derivate e integrali; momento d'inerzia e momento angolare; modulo di Young; teorema di Torricelli sull'efflusso; onde stazionarie; gas reali; legge di Gauss; Biot-Savart; dipolo; carica e scarica del condensatore; effetto fotoelettrico; lenti divergenti e microscopio. Gas reali e numero di Reynolds sono però usciti nel 2025: nell'app sono segnalati come approfondimenti.</li>
   <li>Peso delle unità in CFU: metodi 0,2 · meccanica 1,4 · fluidi 1,2 · onde 0,4 · termodinamica 1 · elettricità e magnetismo 1,2 · radiazioni 0,6.</li></ul></div>`;}
  else{if(E.u25)o+=`<div class="card"><h3>📝 Che cosa è uscito nel 2025</h3><ul class="breve">${E.u25.map(x=>`<li>${x}</li>`).join("")}</ul><p class="src">Fonti: ${LK("prove","testi e soluzioni delle prove 2025")} · ${LK("tb2","analisi del 2° appello")}${E.pit?` · <a href="${E.pit}" target="_blank" rel="noopener">domande commentate</a>`:""}</p></div>`;
   o+=`<div class="card"><h3>🔄 Che cosa cambia nel 2026/27</h3><ul class="breve">${E.n26.map(x=>`<li>${esc(x)}</li>`).join("")}</ul><p class="src">Fonte: ${LK("tbsyl","analisi delle differenze 2025–2026")}</p></div>
   <div class="card"><h3>📐 Peso delle unità</h3><table class="t"><tr><th>Unità</th><th>CFU</th><th>Domande stimate su 31</th></tr>${UNITS.map(u=>`<tr><td>${u.ic} ${esc(u.t)}</td><td>${u.cfu.toLocaleString("it-IT")}</td><td>${u.q}</td></tr>`).join("")}</table></div>`;}
  if(E.map)o+=`<div class="card"><h3>🗺️ Il syllabus voce per voce</h3><p class="lbl" style="margin:0 0 6px">Ogni voce del programma ufficiale 2026/27 e l'argomento dell'app che la tratta. Il segno ✓ indica che hai già segnato come studiati tutti gli argomenti collegati.</p><table class="t"><tr><th>Unità</th><th>Voce del syllabus</th><th>Nell'app</th></tr>${E.map.map(([u,v,ids])=>`<tr><td>${UN[u].ic}</td><td>${esc(v)}</td><td>${ids.map(id=>`<button class="lnk" data-go="${EX}/t/${id}">${esc(TP[id].t)}</button>`).join("<br>")}${ids.every(id=>(S.tp[id]||{}).st)?" ✓":""}</td></tr>`).join("")}</table></div>`;
  const fs=SOURCES.flatMap(g=>g.it).filter(x=>x[2]===EX||(x[2]==="*"&&/MUR|UPO|Prove|Correzione|Soluzioni|syllabus/i.test(x[0])));
  o+=`<div class="card"><h3>🔗 Fonti di ${esc(ename(EX))}</h3>${fs.map(srcRow).join("")}<p class="src"><button class="lnk" data-go="fonti">Tutte le fonti ›</button></p></div>`;
  o+=uffHTML(EX);return o;}

/* ----- Fonti ----- */
const srcRow=([t,u])=>{let h="";try{h=new URL(u).hostname.replace(/^www\./,"");}catch(e){}return `<a class="srcrow" href="${u}" target="_blank" rel="noopener"><span class="grow">${esc(t)}<small>${esc(h)}</small></span><span aria-hidden="true">↗</span></a>`;};
function vFonti(){const n=SOURCES.reduce((a,g)=>a+g.it.length,0);return `<h1>🔗 Fonti</h1><p class="sub">Tutte le ${n} fonti usate per costruire l'app, consultate tra il 9 e l'11 ottobre 2026. Le novità successive arrivano ogni giorno nella pagina «📰 Novità del giorno». Quando un'analisi non ufficiale e il testo ufficiale non coincidono, l'app segue il testo ufficiale (syllabus MUR e pagina UPO).</p>
 ${SOURCES.map(g=>`<div class="card"><h3>${g.g}</h3>${g.it.map(srcRow).join("")}</div>`).join("")}
 <div class="card"><h3>ℹ️ Come sono usate</h3><ul class="breve"><li>Programma e argomenti: solo dai syllabus ufficiali 2026/27.</li><li>Formato, date e regole: decreti MUR, pagina UPO e articoli che li riportano.</li><li>Domande «tipo 2025»: riprendono gli argomenti degli appelli 2025 ricostruiti dalle correzioni pubblicate; i testi originali sono sul sito del MUR (accesso riservato).</li><li>Spiegazioni, esempi ed esercizi sono scritti apposta per l'app: nessun testo è copiato dalle fonti.</li></ul></div>`;}

/* ----- Regole e UPO (comuni ai tre esami) ----- */
function vRegole(){return `<h1>🎓 Regole e UPO</h1><p class="sub">Regole 2026/27 uguali per Fisica, Chimica e Biologia e organizzazione all'Università del Piemonte Orientale. Informazioni verificate all'11 ottobre 2026 (regole e date confermate): controlla sempre gli avvisi ufficiali.</p>
 <div class="grid"><div class="card"><h3>📅 Date</h3><div class="row"><div class="grow"><b>1° appello</b><small>esiti entro il 23 dicembre</small></div><b>gio 10 dic 2026, ore 11</b></div><div class="row"><div class="grow"><b>2° appello</b><small>esiti entro il 20 gennaio</small></div><b>lun 11 gen 2027, ore 11</b></div><div class="row"><div class="grow"><b>Graduatoria nazionale</b><small>poi immatricolazioni dal 22 al 28 gennaio</small></div><b>ven 22 gen 2027, ore 16</b></div><p class="lbl">Nella stessa giornata si fanno Chimica, Fisica e Biologia, con 30 minuti di pausa tra una prova e l'altra. Basta superare ogni prova in uno dei due appelli; se la fai in entrambi conta il voto migliore (almeno 18). Entro le 23:59 del giorno dopo gli esiti si accetta o rifiuta il voto su Universitaly: senza risposta vale come accettato. Dopo la graduatoria: preferenze per i posti rimasti dal 2 al 5 febbraio, primo scorrimento l'8 febbraio, assegnazione ai corsi affini il 16 febbraio, ultime immatricolazioni entro il 12 marzo 2027.</p></div>
 <div class="card"><h3>📝 Com'è fatta ogni prova (novità 2026)</h3><div class="row"><div class="grow">Domande</div><b>31: 21 multipla + 10 completamento</b></div><div class="row"><div class="grow">Tempo</div><b>50 minuti (nel 2025: 45)</b></div><div class="row"><div class="grow">Punteggio</div><b>+1 · −0,1 · 0 se omessa</b></div><div class="row"><div class="grow">Per superarla</div><b>almeno 18/30 (31 = 30 e lode)</b></div><p class="lbl">Risposta multipla: 5 opzioni, una sola giusta. Completamento: uno spazio da riempire con una sola parola, in stampatello. Nel 2025 erano 15 + 16. Contenuto identico in tutte le sedi. Tempo aggiuntivo: fino al 50% con invalidità almeno del 66%, 30% con DSA.</p></div></div>
 <div class="card"><h3>🧠 Strategia</h3><ul class="breve"><li><b>Nelle domande a risposta multipla conviene rispondere:</b> con 5 opzioni e −0,1 per errore, anche tirando a caso si guadagnano in media +0,12 punti; se escludi una o due opzioni, ancora meglio.</li><li>Circa 1 minuto e 37 secondi per domanda: primo giro sulle facili, poi torna sulle altre.</li><li>Niente calcolatrice: numeri pensati per conti a mente. Controlla le unità (cm² → m², L → m³, °C → K).</li><li>Nel completamento: una sola parola o un solo numero; attenzione a singolare/plurale, simboli e ortografia.</li><li><b>Novità 2026:</b> per entrare in graduatoria basta superare anche un solo esame, ma chi ne supera tre sta nella prima sezione (300 + somma dei voti), chi due nella seconda (200 + …), chi uno nella terza. Chi entra con esami mancanti deve recuperare 6 CFU (due superati) o 12 CFU (uno superato). La priorità resta arrivare a 18 in tutti e tre.</li></ul></div>
 <div class="card"><h3>🏛️ All'UPO (Novara e Alessandria)</h3><ul class="breve"><li>Lezioni in presenza dal 1° al 30 settembre al Campus Perrone di Novara; <b>dal 1° ottobre solo online</b> su Zoom, dentro la piattaforma DIR, con registrazioni.</li><li>Frequenza obbligatoria: almeno il <b>51%</b> (presenza in aula, diretta Zoom o visione delle registrazioni su DIR).</li><li>Posti stimati per Medicina: Novara 158 + 13 (extra-UE residenti all'estero), Alessandria 150 + 4.</li><li>Chi è in posizione utile ma ha esami mancanti li recupera nella sede assegnata prima del 2° semestre. Nel 2026 l'UPO ha tenuto corsi di recupero online e tre appelli per materia in ogni sede (Fisica: docenti Ruspa, Arcidiacono, Fava, Sitta).</li><li>Corsi affini all'UPO se non si entra: Scienze biologiche, Biotecnologie, CTF, Farmacia, Infermieristica, Educazione professionale.</li><li>Dal 28 settembre: un solo link Zoom per ogni materia; la frequenza online e delle registrazioni si verifica su DIR (non con UPO Frequency).</li><li>Contatti: <b>semestrefiltro@uniupo.it</b> (UPO) · infosemestreaperto@mur.gov.it (MUR) · inclusione@uniupo.it (disabilità e DSA).</li></ul><p class="src">Fonte: ${LK("upo","pagina UPO sull'accesso a Medicina 2026/27")}</p></div>
 ${uffHTML(null)}<div class="card"><h3>🆓 Piattaforma ufficiale gratuita</h3><p>CRUI, MUR e CISIA hanno aperto ${LK("crui","semestreaperto-medodovet.it")}: MOOC, esercitazioni per unità che seguono le lezioni (al 18 settembre coprivano le prime due unità di ogni materia, complete entro fine ottobre) e, da novembre, <b>simulazioni ufficiali</b> con lo stesso numero di domande, punteggio e tempo. Circa 32 000 iscritti. Esiste anche la piattaforma ${LK("mood","Progetto MOOD")} di 44 atenei. Usale insieme a questa app. Le prove reali del 2025 sono raccolte ${LK("prove","qui")}.</p></div>
 <div class="card"><h3>📰 Aggiornamenti verificati all'11 ottobre 2026</h3><ul class="breve">
  <li><b>15 giugno 2026</b>: il TAR del Lazio respinge il ricorso di un gruppo di docenti contro il semestre filtro; le regole restano valide.</li>
  <li><b>19 giugno 2026</b> (D.M. 704 del 29 maggio): pubblicati i syllabus, riscritti in chiave biomedica; Chimica la più cambiata (da 8 a 7 unità), Fisica alleggerita, Biologia quasi uguale; 20–30% di esercitazioni.</li>
  <li><b>10 luglio</b> (D.M. 941): 21 + 10 domande in 50 minuti, graduatoria in 3 sezioni (+300, +200, +100), voto migliore tra i due appelli, almeno 5 sedi per il corso affine.</li>
  <li><b>13 luglio</b> (decreto direttoriale 249): appelli il 10 dicembre 2026 e l'11 gennaio 2027.</li>
  <li><b>15 luglio</b>: il TAR del Lazio chiede chiarimenti al MUR sui criteri di selezione; nessuna modifica alle regole finora.</li>
  <li><b>3–6 agosto</b>: 62 200 iscritti al semestre (oltre 52 000 per Medicina); posti totali 30 225 (D.M. 1004), di cui 18 889 per Medicina in italiano nelle università statali.</li>
  <li><b>18 settembre</b>: la piattaforma nazionale aggiunge esercizi di Fisica, Chimica e Biologia; simulazioni da novembre.</li>
  <li><b>4–5 agosto</b>: il Consiglio di Stato (ordinanza 3347/2026) chiede al MUR di far scorrere la graduatoria 2025/26 sui posti rimasti vacanti; non cambia le regole 2026/27.</li>
  <li><b>28 settembre</b> (UPO): dal 1° ottobre lezioni solo online su Zoom/DIR; registrazioni valide per la frequenza.</li></ul>
  <p class="lbl">Le notizie successive, con data e fonte, sono nella pagina <button class="lnk" data-go="novita">📰 Novità del giorno</button>, che si aggiorna da sola.</p>
  <p class="src">Fonti: ${LK("nov","Futura, novità 2026/27")} · ${LK("guida","Orizzonte Scuola, guida date")} · ${LK("tar","News Istruzione, TAR")} · ${LK("upoen","UPO, aggiornamenti")} · tutte le fonti nella pagina <button class="lnk" data-go="fonti">🔗 Fonti</button></p></div>
 <div class="card"><h3>📚 Syllabus ufficiali 2026/27</h3>${EXORD.map(k=>`<div class="row"><span class="ubadge" style="--uc:var(${EXAMS[k].col})">${EXAMS[k].ic}</span><div class="grow">${esc(EXAMS[k].t)}</div><a class="btn sm" href="${EXAMS[k].syl}" target="_blank" rel="noopener">PDF</a></div>`).join("")}<p class="src">Pagina MUR: ${LK("mur","syllabus del semestre aperto 2026/27")} · ${LK("date","date e formato delle prove")}</p></div>`;}

/* ----- Progressi e copie ----- */
function vProg(){const days=[];for(let i=13;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);days.push(iso(d));}
  const per=days.map(d=>EXORD.map(k=>Rt.exams[k].days[d]||0)),mx=Math.max(1,...per.map(a=>a.reduce((x,y)=>x+y,0)));
  let o=`<h1>📈 Progressi e copie</h1><p class="sub">Tutto viene salvato da solo su questo iPad: una copia al giorno resta sul dispositivo per 30 giorni. Con «Salva copia su File / iCloud» in fondo alla pagina puoi conservarli o passarli a un altro iPad.</p>
  <div class="kpi">${EXORD.map(k=>`<div><b>${withExam(k,overall)}%</b><span>${EXAMS[k].ic} ${esc(ename(k))}</span></div>`).join("")}<div><b>${EXORD.reduce((a,k)=>a+Object.values(Rt.exams[k].qs).reduce((x,s)=>x+s.ok+s.ko,0),0)}</b><span>risposte date in totale</span></div></div>
  <div class="card"><h3>Ultimi 14 giorni (esercizi svolti)</h3><div style="display:flex;gap:4px;align-items:flex-end;height:90px">${days.map((d,i)=>{const n=per[i].reduce((x,y)=>x+y,0);return `<div title="${fmtD(d)}: ${n}" style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px;height:100%;justify-content:flex-end">${n?`<span class="lbl" style="font-size:10px;font-weight:700">${n}</span>`:""}<div style="width:100%;height:${n/mx*60}px;min-height:${n?3:0}px;background:var(--accent);border-radius:4px"></div><span class="lbl" style="font-size:10px">${dOf(d).getDate()}</span></div>`;}).join("")}</div></div>`;
  o=o.replace('<div class="kpi">',aspettoHTML()+'<div class="kpi">');   /* l'autodiagnosi lavora in silenzio: non si mostra allo studente */
  o+=EXORD.map(k=>withExam(k,()=>fold("prog-"+k,`<h3>${E.ic} ${esc(E.t)} · argomento per argomento</h3>`,`<table class="t"><tr><th>Argomento</th><th>${QB.length?"Giuste":"Autovalutazione"}</th><th>Stato</th></tr>${TOPICS.map(t=>{const s=S.tp[t.id]||{},sc=tScore(t.id);return `<tr><td>${UN[t.u].ic} <a href="#${k}/t/${t.id}" style="color:inherit">${esc(t.t)}</a>${s.st?" ✓":""}</td><td>${hasQ(t.id)?`${s.ok||0}/${(s.ok||0)+(s.ko||0)}`:(s.self?SELF[s.self-1][0]:"—")}</td><td><span class="pill ${stLab(sc)[1]}">${sc}%</span></td></tr>`;}).join("")}</table><div class="btns"><button class="btn sm" data-go="${k}/arg">Apri ${esc(ename(k))} ›</button></div>`,false))).join("");
  o+=`<div class="card"><h3>Copie e ripristino</h3><p class="lbl">Il salvataggio è automatico (memoria del browser + database del dispositivo). Per passare i dati su un altro iPad o tenerne una copia, usa «Salva copia su File / iCloud» in fondo alla pagina. Sull'altro iPad, qui, tocca «Ripristina da una copia».</p>
  ${restoreAskHTML()}<div class="btns"><label class="btn" style="cursor:pointer">Ripristina da una copia<input type="file" id="fzImp" accept="application/json,.json" hidden></label><button class="btn danger" id="fzReset">Azzera i progressi del semestre filtro</button></div></div>`;
  return o;}


/* ----- Che cosa fa l'app (descrizione breve per lo studente) ----- */
function vGuida(){return `<h1>ℹ️ Che cosa fa questa app</h1><p class="sub">«Semestre filtro» è un'app per iPad che prepara ai tre esami del semestre filtro di Medicina 2026/27 all'UPO: Fisica, Chimica e Biologia. Segue i programmi ufficiali del Ministero (fonte: ${LK("mur","syllabus MUR del semestre aperto 2026/27")}) e lo stesso formato d'esame: 31 domande in 50 minuti.</p>
 <div class="card"><ul class="breve">
  <li>🧭 <b>Test d'ingresso:</b> capisce da dove parti e prepara il tuo piano di studio fino al 10 dicembre.</li>
  <li>📚 <b>Argomenti:</b> spiegazione, animazione interattiva, esempi svolti, formule e trappole d'esame.</li>
  <li>✏️ <b>Esercizi e simulazioni:</b> serie da 10 domande corrette e spiegate, simulazioni a tempo e le prove reali del 2025 da rifare. Le domande cambiano ogni volta; quelle uscite davvero all'esame sono segnate con 📌.</li>
  <li>🗂️ <b>Errori:</b> dai tuoi errori nasce un obiettivo di studio con ripasso guidato; ogni prova resta salvata con data e ora.</li>
  <li>📰 <b>Novità del giorno:</b> le notizie ufficiali sul semestre filtro, con la fonte.</li>
  <li>💾 Salva tutto da sola sull'iPad e funziona anche senza internet.</li></ul>
  <p class="src" style="margin-top:10px"><b>Da dove vengono le informazioni:</b> programmi d'esame dai ${LK("mur","syllabus ufficiali del MUR 2026/27")}; regole, date e formato della prova dal ${SOURCES[0]&&SOURCES.find(g=>g.g.startsWith("🏛️"))?`<a href="${SOURCES.find(g=>g.g.startsWith("🏛️")).it[1][1]}" target="_blank" rel="noopener">D.M. 941/2026</a> e dal <a href="${SOURCES.find(g=>g.g.startsWith("🏛️")).it[2][1]}" target="_blank" rel="noopener">D.D. 249/2026</a> del MUR`:"MUR"}; organizzazione a Novara e Alessandria dalla ${LK("upo","pagina UPO sull'accesso a Medicina 2026/27")}; domande reali dalle ${LK("prove","prove nazionali del 2025")}. Spiegazioni ed esercizi sono scritti apposta sulla base di questi testi. Elenco completo nella pagina <button class="lnk" data-go="fonti">🔗 Fonti</button>.</p>
  <div class="btns"><button class="btn pri" data-go="fis/test">Inizia dal test d'ingresso</button><button class="btn" data-go="home">Torna alla home</button></div></div>`;}

/* ----- Installa su un altro iPad ----- */
function vInstalla(){return `<h1>📲 Installa su un altro iPad</h1><p class="sub">«Semestre filtro» esiste anche come app a sé, da mettere sulla schermata Home di qualsiasi iPad o iPhone. È gratuita, funziona anche senza internet e si aggiorna da sola.</p>
 <div class="grid"><div class="card"><h3>1 · Apri l'indirizzo sull'altro iPad</h3><p style="margin-top:0">Inquadra il codice con la <b>Fotocamera</b> dell'altro iPad e tocca il link che compare, oppure scrivi l'indirizzo in Safari.</p>
  <div class="qrbox">${window.QR_SVG||""}</div><div class="formula" style="white-space:normal;word-break:break-all">${APP_URL}</div>
  <div class="btns"><button class="btn" id="cpUrl">Copia l'indirizzo</button>${navigator.share?'<button class="btn" id="shUrl">Invia (Messaggi, Mail, AirDrop)</button>':""}</div></div>
 <div class="card"><h3>2 · Aggiungi alla schermata Home</h3><ol class="breve"><li>Usa <b>Safari</b> (con altri browser l'app non si installa bene).</li><li>Tocca il pulsante <b>Condividi</b> (il quadrato con la freccia in su), in alto a destra.</li><li>Scegli <b>«Aggiungi alla schermata Home»</b>, lascia il nome «Semestre filtro» e tocca <b>Aggiungi</b>.</li><li>Da quel momento apri l'app dall'icona blu con il battito: si apre a tutto schermo e si aggiorna da sola quando ci sono novità.</li></ol></div>
 <div class="card"><h3>3 · Se vuoi portare i progressi</h3><ol class="breve"><li>Su questo iPad tocca <b>«💾 Salva copia su File / iCloud»</b> in fondo alla pagina e salva su <b>iCloud Drive</b> (oppure inviala con AirDrop).</li><li>Sull'altro iPad, nell'app: <b>📈 Progressi e copie → Ripristina da una copia</b> e scegli il file.</li></ol><p class="lbl">Ogni iPad tiene i suoi dati: non c'è una sincronizzazione automatica, quindi conviene usare l'app soprattutto su un iPad e fare la copia quando si cambia.</p></div>
 <div class="card"><h3>🔒 Privacy</h3><p style="margin:0">L'indirizzo è pubblico ma contiene solo il programma e gli esercizi: test, risposte, simulazioni e progressi restano solo sul dispositivo (e nelle copie che salvi tu).</p></div></div>`;}
/* ================= EVENTI ================= */
function bind(){if(curT&&QFOCUS){const qid=QFOCUS;QFOCUS=null;const d=document.querySelector('details[data-fold="tp-q"]');if(d)d.open=true;setTimeout(()=>{const b=document.querySelector(`.q[data-q="${qid}"]`);if(b){b.scrollIntoView({block:"center"});b.classList.add("qhl");setTimeout(()=>b.classList.remove("qhl"),2500);}},80);}
  if(curT){const t=TP[curT];if(t.anim)mountAnim($("animBox"),t.anim,t.animOpt);const b=$("tStudied");if(b)b.onclick=()=>{const s=S.tp[curT]||{};s.st=!s.st;S.tp[curT]=s;save();render();toast(s.st?"Segnato come studiato":"Tolto il segno");};}
  if(view==="ex:sim"&&S.run){tickSim();simTimer=setInterval(tickSim,1000);}
  if(view==="ex:arg"&&!curT&&argU){const e=$("u-"+argU);if(e)setTimeout(()=>e.scrollIntoView({block:"start"}),30);argU=null;}}
document.addEventListener("click",e=>{
  const fa=e.target.closest("[data-fall]");if(fa){const all=[...document.querySelectorAll("#main details.fold")];const v=fa.dataset.fall==="t"?!all.every(d=>d.open):fa.dataset.fall==="1";all.forEach(d=>{d.open=v;setFold(d.dataset.fold,v);});return;}
  const g=e.target.closest("[data-go]");if(g){if(g.dataset.u)argU=g.dataset.u;if(g.closest("#side")){PR=null;SIMV=null;}go(g.dataset.go);return;}
  const pr=e.target.closest("[data-pr]");if(pr){startPR(pr.dataset.pr);return;}
  const hs=e.target.closest("[data-hsim]");if(hs){SIMV=+hs.dataset.hsim;go(EX+"/sim");return;}
  const sv=e.target.closest("[data-simv]");if(sv){SIMV=+sv.dataset.simv;render();return;}
  const se=e.target.closest("#selfEv button");if(se&&curT){const s=S.tp[curT]||{};s.self=+se.dataset.v;S.tp[curT]=s;save();se.parentNode.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b===se));toast("Autovalutazione salvata");side();const ts=$("tSub");if(ts)ts.textContent=stLab(tScore(curT))[0]+" · "+tScore(curT)+"%";return;}
  const ps=e.target.closest("#ptSchool button");if(ps){PTA.school=ps.textContent;ps.parentNode.querySelectorAll("button").forEach(b=>b.classList.toggle("on",b===ps));return;}
  const pq=e.target.closest("[data-pt] .opt");if(pq){const i=+pq.closest("[data-pt]").dataset.pt,j=+pq.dataset.o;PTA.a[i]=PTA.a[i]===j?undefined:j;pq.parentNode.querySelectorAll(".opt").forEach(b=>b.classList.toggle("sel",PTA.a[i]===+b.dataset.o));S.ptDraft={a:PTA.a,school:PTA.school,sel:PTA.sel,seed:PTA.seed,ts:new Date().toISOString()};save();return;}
  if(e.target.closest("#ptDone")){const unit={};let sc=0;PTA.sel.forEach((pi,i)=>{const q=PT[pi];unit[q.u]=unit[q.u]||[0,2];if(PTA.a[i]===q.a){unit[q.u][0]++;sc++;}});const r=sc/PTA.sel.length;S.ptSeen=S.ptSeen||{};PTA.sel.forEach(pi=>S.ptSeen[pi]=(S.ptSeen[pi]||0)+1);S.ptSets=(S.ptSets||[]).concat([PTA.sel.slice().sort((x,y)=>x-y).join(",")]).slice(-60);
    const lev=r>=.78?"avanzato":r>=.43?"intermedio":"base";S.pt={date:today(),score:sc,unit,lev,sel:PTA.sel.slice(),ans:PTA.sel.map((pi,i)=>PTA.a[i]==null?null:PT[pi].o[PTA.a[i]])};try{logPT(sc,lev);}catch(e){}S.ptDraft=null;ensureGoal();if(PTA.school){S.school=PTA.school;S.pt.school=PTA.school;if(!Rt.school)Rt.school=PTA.school;}PTA=null;save();render();toast("Test salvato: piano di studio aggiornato");return;}
  if(e.target.closest("#ptRedo")){PTA=newPTA();S.ptDraft=null;render();return;}
  const op=e.target.closest('.q[data-ctx] .opt');if(op){const box=op.closest(".q"),q=QI[box.dataset.q];const ok=answerImmediate(box,q,+op.dataset.o);afterPR(box,ok);return;}
  const ck=e.target.closest('.q[data-ctx] [data-chk]');if(ck){const box=ck.closest(".q"),v=box.querySelector("input").value.trim();if(!v){toast("Scrivi la risposta o tocca «Non so»");return;}const ok=answerImmediate(box,QI[box.dataset.q],v);afterPR(box,ok);return;}
  const sk=e.target.closest('.q[data-ctx] [data-skip]');if(sk){const box=sk.closest(".q");const ok=answerImmediate(box,QI[box.dataset.q],null);afterPR(box,ok);return;}
  if(e.target.closest("#prNext")){PR.i++;prSave();render();return;}
  if(e.target.closest("#restoreYes")&&RESTORE){idb("readwrite","sf-prima-del-ripristino",JSON.stringify(Rt)).catch(()=>{});Rt=RESTORE;RESTORE=null;histMigrate();useExam(EX);save();render();toast("Progressi ripristinati");return;}
  if(e.target.closest("#restoreNo")){RESTORE=null;render();toast("Ripristino annullato");return;}
  if(e.target.closest("#prResume")){if(prResume())render();return;}
  if(e.target.closest("#prDrop")){S.prDraft=null;save();render();return;}
  if(e.target.closest("#prStop")){PR.list=PR.list.slice(0,PR.i+($("prBox").querySelector(".q").dataset.done?1:0));PR.i=PR.list.length;S.prDraft=null;save();render();return;}
  const rl=e.target.closest("[data-real]");if(rl){if(S.run){go(EX+"/sim");return;}const k=rl.dataset.real,ids=QB.filter(q=>q.r===k).sort((a,b)=>a.rn-b.rn).map(q=>q.id);SIMV=null;S.run={start:Date.now(),q:ids,a:{},min:45,real:k};save();if(location.hash!=="#"+EX+"/sim")location.hash=EX+"/sim";else render();return;}
  if(e.target.closest("#simStart")){if(S.run){render();return;}if(QB.length<31){toast("Servono almeno 31 domande");return;}SIMV=null;S.run={start:Date.now(),q:buildSim(),a:{}};save();view="ex:sim";history.replaceState(null,"","#"+EX+"/sim");render();return;}
  if(e.target.closest("#simBack")){SIMV=null;render();return;}
  if(e.target.closest("#cpUrl")){try{navigator.clipboard.writeText(APP_URL).then(()=>toast("Indirizzo copiato"),()=>toast(APP_URL));}catch(_){toast(APP_URL);}return;}
  if(e.target.closest("#shUrl")){navigator.share({title:"Semestre filtro",text:"App per preparare gli esami del semestre filtro di Medicina",url:APP_URL}).catch(()=>{});return;}
  const sEnd=e.target.closest("#simEnd")||e.target.closest("#simEnd2");if(sEnd){const n=S.run.q.filter((id,i)=>S.run.a[i]==null||S.run.a[i]==="").length;if(!armed(sEnd,n?`Tocca di nuovo per consegnare (${n} vuote)`:"Tocca di nuovo per consegnare"))return;finishSim(false);return;}
  const so=e.target.closest("[data-si] .opt");if(so&&S.run){const i=+so.closest("[data-si]").dataset.si,j=+so.dataset.o;S.run.a[i]=S.run.a[i]===j?null:j;so.parentNode.querySelectorAll(".opt").forEach(b=>b.classList.toggle("sel",S.run.a[i]===+b.dataset.o));save();return;}
  const rz=e.target.closest("#fzReset");if(rz){if(armed(rz,"Tocca di nuovo per cancellare tutto")){idb("readwrite","sf-prima-del-reset-"+Date.now(),JSON.stringify(Rt)).catch(()=>{});Rt=norm(null);useExam(EX);save();render();toast("Progressi azzerati");}return;}
});
function afterPR(box,ok){if(box.dataset.ctx!=="pr")return;if(ok)PR.ok++;const q=QI[box.dataset.q],inp=box.querySelector("input"),o=box.querySelector(".opt.wrong");
  (PR.res=PR.res||[]).push({id:box.dataset.q,ok:!!ok,a:q?(q.k==="m"?(o?q.o[+o.dataset.o]:null):(inp&&inp.value.trim()||null)):null});prSave();const n=$("prNext");if(n){n.hidden=false;n.focus();}}
let svT2=null;
document.addEventListener("input",e=>{const i=e.target.closest("[data-si] input");if(i&&S.run){S.run.a[+i.closest("[data-si]").dataset.si]=i.value.trim();clearTimeout(svT2);svT2=setTimeout(save,400);}});
document.addEventListener("keydown",e=>{if(e.key==="Enter"){const i=e.target.closest('.q[data-ctx] input');if(i){e.preventDefault();i.closest(".q").querySelector("[data-chk]").click();}}});
document.addEventListener("change",e=>{if(e.target.id!=="fzImp")return;const f=e.target.files[0];if(!f)return;const rd=new FileReader();rd.onload=()=>{try{const o=JSON.parse(rd.result);let r=null;
  if(o&&o.semestre)r=norm(o.semestre);else if(o&&o.exams)r=norm(o);else if(o&&o.fisica)r=migrate(o.fisica);else if(o&&o.tp&&o.qs)r=migrate(o);if(!r)throw 0;
  RESTORE=r;render();setTimeout(()=>{const c=$("restoreAsk");if(c)c.scrollIntoView({block:"center"});},50);}catch(_){toast("Nella copia non ci sono dati del semestre filtro");}};rd.readAsText(f);e.target.value="";});
/* ripristino: prima si mostra che cosa contiene la copia e si chiede conferma */
let RESTORE=null;
function restoreAskHTML(){if(!RESTORE)return "";const r=RESTORE,cur=Rt.savedAt?new Date(Rt.savedAt).toLocaleString("it-IT",{day:"numeric",month:"long",hour:"2-digit",minute:"2-digit"}):"—",cp=r.savedAt?new Date(r.savedAt).toLocaleString("it-IT",{day:"numeric",month:"long",hour:"2-digit",minute:"2-digit"}):"data sconosciuta";
  const n=x=>EXORD.reduce((a,k)=>a+Object.values((x.exams[k]||{}).qs||{}).reduce((b,q)=>b+(q.ok||0)+(q.ko||0),0),0);
  return `<div class="card" id="restoreAsk" style="border:2px solid var(--warn)"><h3>⚠️ Sostituire i progressi di questo iPad?</h3><p style="margin:0 0 6px">Copia del <b>${cp}</b> con ${n(r)} risposte. Su questo iPad ora ci sono ${n(Rt)} risposte (ultimo salvataggio: ${cur}). I progressi attuali verranno sostituiti; ne resta comunque una copia di sicurezza sul dispositivo.</p><div class="btns"><button class="btn danger" id="restoreYes">Sì, sostituisci</button><button class="btn" id="restoreNo">Annulla</button></div></div>`;}
window.addEventListener("hashchange",route);
window.addEventListener("storage",e=>{if(e.key===KEY&&e.newValue){Rt=norm(JSON.parse(e.newValue));useExam(EX);if(!S.run)render();}});
document.addEventListener("visibilitychange",()=>{if(document.visibilityState==="hidden"){try{diagnosi(false);}catch(e){}window.__flush();}else{if(S.run&&view==="ex:sim")tickSim();diagDaily();newsRefresh(false);}});
try{histMigrate();}catch(e){}try{cpFix();}catch(e){}try{if(navigator.storage&&navigator.storage.persist)navigator.storage.persist().catch(()=>{});}catch(e){}
window.addEventListener("pagehide",()=>{try{diagnosi(false);}catch(e){}window.__flush();});
UI();route();recover();diagDaily();newsRefresh(true);if(!Rt.sum){Rt.sum=summaryAll();try{localStorage.setItem(KEY,JSON.stringify(Rt));}catch(e){}}
